<script>
let running=false,start=0,elapsed=0,raf,laps=[];
function fmt(ms){const m=Math.floor(ms/60000),s=Math.floor((ms%60000)/1000),ml=ms%1000;
  return `${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}.${String(ml).padStart(3,'0')}`}
function tick(){elapsed=Date.now()-start;document.getElementById('display').textContent=fmt(elapsed);raf=requestAnimationFrame(tick)}
function toggle(){if(running){cancelAnimationFrame(raf);running=false;document.getElementById('startBtn').textContent='Resume'}
  else{start=Date.now()-elapsed;running=true;document.getElementById('startBtn').textContent='Pause';tick()}}
function lap(){if(!running)return;laps.push(elapsed);const el=document.getElementById('laps');
  el.innerHTML=laps.map((l,i)=>`<div class="lap"><span>Lap ${i+1}</span><span>${fmt(l)}</span></div>`).reverse().join('')}
function reset(){cancelAnimationFrame(raf);running=false;elapsed=0;laps=[];
  document.getElementById('display').textContent='00:00.000';document.getElementById('laps').innerHTML='';
  document.getElementById('startBtn').textContent='Start'}
</script></body></html>
