</style></head><body>
<div class="app">
<h1>Typing Speed Test</h1>
<div class="stats">WPM: <span id="wpm">0</span> | Accuracy: <span id="acc">100%</span> | Time: <span id="time">60s</span></div>
<div class="text" id="text"></div>
<input id="input" placeholder="Start typing..." oninput="onType()" autofocus>
<div class="result" id="result"><h2 id="resultText"></h2><p id="resultStats"></p><button onclick="init()">Try Again</button></div>
</div>
<script>
const WORDS='the be to of and a in that have i it for not on with he as you do at this but his by from they we say her she or an will my one all would there their what so up out if about who get which go me when make can like time no just him know take people into year your good some could them see other than then now look only come its over think also back after use two how our work first well way even new want because any these give day most us'.split(' ');
let text,pos,correct,startTime,timer,duration=60;
function init(){text='';for(let i=0;i<80;i++)text+=WORDS[Math.floor(Math.random()*WORDS.length)]+' ';
  text=text.trim();pos=0;correct=0;startTime=null;clearInterval(timer);duration=60;
  document.getElementById('input').value='';document.getElementById('input').disabled=false;
  document.getElementById('result').style.display='none';document.getElementById('time').textContent='60s';
  document.getElementById('wpm').textContent='0';document.getElementById('acc').textContent='100%';renderText()}
function renderText(){const el=document.getElementById('text');let html='';
  for(let i=0;i<text.length;i++){let cls='pending';if(i<pos)cls=text[i]===getTyped()[i]?'correct':'wrong';if(i===pos)cls='current';
    html+=`<span class="${cls}">${text[i]}</span>`}el.innerHTML=html}
function getTyped(){return document.getElementById('input').value}
function onType(){if(!startTime){startTime=Date.now();timer=setInterval(tick,1000)}
  pos=getTyped().length;correct=0;for(let i=0;i<pos;i++)if(getTyped()[i]===text[i])correct++;
  const elapsed=(Date.now()-startTime)/60000;const wpm=Math.round((correct/5)/Math.max(elapsed,.01));
  const acc=pos?Math.round(correct/pos*100):100;
  document.getElementById('wpm').textContent=wpm;document.getElementById('acc').textContent=acc+'%';
  renderText();if(pos>=text.length)finish()}
function tick(){duration--;document.getElementById('time').textContent=duration+'s';if(duration<=0)finish()}
function finish(){clearInterval(timer);document.getElementById('input').disabled=true;
  const elapsed=(Date.now()-startTime)/60000;const wpm=Math.round((correct/5)/elapsed);const acc=pos?Math.round(correct/pos*100):100;
  document.getElementById('result').style.display='block';
  document.getElementById('resultText').textContent=`${wpm} WPM`;
  document.getElementById('resultStats').textContent=`Accuracy: ${acc}% | Characters: ${pos}`}
init();
</script></body></html>
