<script>
let data={todo:[{title:'Design landing page',tag:'feat'},{title:'Fix login bug',tag:'bug'}],progress:[{title:'Build API endpoints',tag:'task'}],done:[{title:'Setup database',tag:'task'}]};
const COLS=[{id:'todo',label:'To Do'},{id:'progress',label:'In Progress'},{id:'done',label:'Done'}];
function render(){const board=document.getElementById('board');board.innerHTML='';
  COLS.forEach(col=>{const count=data[col.id].length;
    let html=`<div class="column"><div class="col-header">${col.label} <span>${count}</span></div><div class="col-body" id="${col.id}" ondragover="ev(event)" ondrop="drop(event,'${col.id}')" ondragleave="leave(event)">`;
    data[col.id].forEach((card,i)=>{html+=`<div class="card" draggable="true" ondragstart="drag(event,'${col.id}',${i})" ondragend="dragEnd(event)"><div class="card-title">${card.title}</div><span class="card-tag tag-${card.tag}">${card.tag}</span></div>`});
    html+=`</div><button class="add-btn" onclick="add('${col.id}')">+ Add card</button></div>`;board.innerHTML+=html})}
let dragSrc=null;
function drag(e,col,idx){dragSrc={col,idx};e.target.classList.add('dragging');e.dataTransfer.effectAllowed='move'}
function dragEnd(e){e.target.classList.remove('dragging')}
function ev(e){e.preventDefault();e.currentTarget.classList.add('dragover')}
function leave(e){e.currentTarget.classList.remove('dragover')}
function drop(e,targetCol){e.preventDefault();e.currentTarget.classList.remove('dragover');if(!dragSrc)return;
  const card=data[dragSrc.col].splice(dragSrc.idx,1)[0];data[targetCol].push(card);dragSrc=null;save();render()}
function add(col){const title=prompt('Card title:');if(!title)return;const tag=prompt('Tag (feat/bug/task):','task')||'task';
  data[col].push({title,tag});save();render()}
function save(){localStorage.setItem('kanban',JSON.stringify(data))}
const saved=localStorage.getItem('kanban');if(saved)data=JSON.parse(saved);render();
</script></body></html>
