<h1>2048</h1>
<div class="score-row"><div class="score-box"><div class="label">Score</div><div class="val" id="score">0</div></div><div class="score-box"><div class="label">Best</div><div class="val" id="best">0</div></div></div>
<div class="board" id="board"></div>
<div id="msg"></div>
<button onclick="init()">New Game</button>
<script>
let grid,score,best=+localStorage.getItem('2048best')||0;
function init(){grid=Array(16).fill(0);score=0;addTile();addTile();render();document.getElementById('msg').textContent='';document.getElementById('best').textContent=best}
function addTile(){const empty=[];grid.forEach((v,i)=>{if(!v)empty.push(i)});if(!empty.length)return;
  const idx=empty[Math.floor(Math.random()*empty.length)];grid[idx]=Math.random()<.9?2:4}
function render(){const b=document.getElementById('board');b.innerHTML='';
  grid.forEach(v=>{const d=document.createElement('div');d.className='tile t'+v;d.textContent=v||'';b.appendChild(d)});
  document.getElementById('score').textContent=score;if(score>best){best=score;localStorage.setItem('2048best',best);document.getElementById('best').textContent=best}}
function slide(row){let a=row.filter(v=>v);for(let i=0;i<a.length-1;i++){if(a[i]===a[i+1]){a[i]*=2;score+=a[i];a.splice(i+1,1)}}
  while(a.length<4)a.push(0);return a}
function move(dir){let moved=false;const g=[...grid];
  if(dir==='left')for(let r=0;r<4;r++){const row=grid.slice(r*4,r*4+4);const s=slide(row);for(let c=0;c<4;c++)grid[r*4+c]=s[c]}
  if(dir==='right')for(let r=0;r<4;r++){const row=grid.slice(r*4,r*4+4).reverse();const s=slide(row).reverse();for(let c=0;c<4;c++)grid[r*4+c]=s[c]}
  if(dir==='up')for(let c=0;c<4;c++){const col=[grid[c],grid[c+4],grid[c+8],grid[c+12]];const s=slide(col);for(let r=0;r<4;r++)grid[r*4+c]=s[r]}
  if(dir==='down')for(let c=0;c<4;c++){const col=[grid[c],grid[c+4],grid[c+8],grid[c+12]].reverse();const s=slide(col).reverse();for(let r=0;r<4;r++)grid[r*4+c]=s[r]}
  moved=g.some((v,i)=>v!==grid[i]);if(moved){addTile();render();checkEnd()}}
function checkEnd(){if(grid.includes(2048)){document.getElementById('msg').textContent='You win!'}
  if(!grid.includes(0)){let canMove=false;for(let r=0;r<4&&!canMove;r++)for(let c=0;c<3;c++){if(grid[r*4+c]===grid[r*4+c+1])canMove=true}
    for(let c=0;c<4&&!canMove;c++)for(let r=0;r<3;r++){if(grid[r*4+c]===grid[(r+1)*4+c])canMove=true}
    if(!canMove)document.getElementById('msg').textContent='Game Over!'}}
document.addEventListener('keydown',e=>{if(e.key==='ArrowLeft')move('left');if(e.key==='ArrowRight')move('right');if(e.key==='ArrowUp'){e.preventDefault();move('up')}if(e.key==='ArrowDown'){e.preventDefault();move('down')}});
init();
</script></body></html>
