Here's the pattern — IntersectionObserver + paginated fetch:

```javascript
// 1. The sentinel element sits at the bottom of your list
// <div id="list"></div>
// <div id="sentinel"></div>

let page = 1;
let loading = false;
let hasMore = true;

const observer = new IntersectionObserver((entries) => {
  if (entries[0].isIntersecting && !loading && hasMore) {
    loadMore();
  }
}, { threshold: 0.1 });

observer.observe(document.getElementById('sentinel'));

async function loadMore() {
  loading = true;
  showSpinner();

  const res = await fetch(`/api/items?page=${page}&limit=20`);
  const { items, totalPages } = await res.json();

  items.forEach(item => {
    const el = document.createElement('div');
    el.className = 'item';
    el.innerHTML = `<h3>${item.title}</h3><p>${item.excerpt}</p>`;
    document.getElementById('list').appendChild(el);
  });

  page++;
  hasMore = page <= totalPages;
  loading = false;
  hideSpinner();

  if (!hasMore) {
    observer.disconnect();
    document.getElementById('sentinel').textContent = 'No more items';
  }
}
```

## Why IntersectionObserver over scroll events:
1. **Performance** — no scroll listener firing 60fps
2. **Clean API** — observe/unobserve/disconnect
3. **Threshold control** — trigger before fully visible (preload)
4. **Works in containers** — not just window scroll

## Key gotchas:
- Always guard with `loading` flag to prevent double-fetch
- Disconnect observer when no more pages
- Set `threshold: 0.1` so it triggers slightly before visible (smoother UX)
- Add a CSS `min-height` to sentinel so it's always observable

## Complete HTML example:
```html
<!DOCTYPE html>
<html><head><style>
body{font-family:system-ui;max-width:600px;margin:0 auto;padding:20px;background:#111;color:#eee}
.item{padding:16px;margin:8px 0;background:#1a1a2e;border-radius:8px}
.item h3{margin-bottom:4px;color:#60a5fa}
#sentinel{padding:20px;text-align:center;color:#666}
.spinner{display:inline-block;width:20px;height:20px;border:2px solid #333;border-top-color:#60a5fa;border-radius:50%;animation:spin .6s linear infinite}
@keyframes spin{to{transform:rotate(360deg)}}
</style></head><body>
<h1>Infinite Scroll</h1>
<div id="list"></div>
<div id="sentinel"><div class="spinner"></div></div>
<script>
let page=1,loading=false;
const observer=new IntersectionObserver(entries=>{if(entries[0].isIntersecting&&!loading)load()},{threshold:0.1});
observer.observe(document.getElementById('sentinel'));
async function load(){loading=true;
  await new Promise(r=>setTimeout(r,500));
  const list=document.getElementById('list');
  for(let i=0;i<10;i++){const n=(page-1)*10+i+1;list.insertAdjacentHTML('beforeend',`<div class="item"><h3>Item ${n}</h3><p>Content for item ${n}</p></div>`)}
  page++;loading=false;if(page>10){observer.disconnect();document.getElementById('sentinel').textContent='All loaded'}}
</script></body></html>
