</style></head><body>
<canvas id="c" width="480" height="360"></canvas>
<div id="ui"><span>Score: <b id="score">0</b></span><span>Lives: <b id="lives">3</b></span></div>
<script>
const c=document.getElementById('c'),ctx=c.getContext('2d'),W=c.width,H=c.height;
const ROWS=4,COLS=8,BW=55,BH=18,BPAD=5,BTOP=40;
let paddle={x:W/2-40,w:80,h:12},ball={x:W/2,y:H-40,dx:3,dy:-3,r:6};
let bricks=[],score=0,lives=3,running=true;
function initBricks(){bricks=[];for(let r=0;r<ROWS;r++)for(let c2=0;c2<COLS;c2++)bricks.push({x:c2*(BW+BPAD)+20,y:r*(BH+BPAD)+BTOP,w:BW,h:BH,alive:true,color:['#e94560','#f97316','#eab308','#4ade80'][r]})}
function reset(){ball={x:W/2,y:H-40,dx:3*(Math.random()>.5?1:-1),dy:-3,r:6};paddle.x=W/2-40}
function update(){if(!running)return;
  ball.x+=ball.dx;ball.y+=ball.dy;
  if(ball.x<ball.r||ball.x>W-ball.r)ball.dx*=-1;
  if(ball.y<ball.r)ball.dy*=-1;
  if(ball.y>H){lives--;document.getElementById('lives').textContent=lives;if(lives<=0){running=false;return}reset();return}
  if(ball.y+ball.r>=H-paddle.h-10&&ball.x>=paddle.x&&ball.x<=paddle.x+paddle.w){ball.dy=-Math.abs(ball.dy);ball.dx+=(ball.x-(paddle.x+paddle.w/2))*0.08}
  for(const b of bricks){if(!b.alive)continue;if(ball.x>b.x&&ball.x<b.x+b.w&&ball.y>b.y&&ball.y<b.y+b.h){b.alive=false;ball.dy*=-1;score++;document.getElementById('score').textContent=score}}}
function draw(){ctx.fillStyle='#1a1a2e';ctx.fillRect(0,0,W,H);
  ctx.fillStyle='#fff';ctx.fillRect(paddle.x,H-paddle.h-10,paddle.w,paddle.h);
  ctx.beginPath();ctx.arc(ball.x,ball.y,ball.r,0,Math.PI*2);ctx.fillStyle='#e94560';ctx.fill();
  for(const b of bricks){if(!b.alive)continue;ctx.fillStyle=b.color;ctx.fillRect(b.x,b.y,b.w,b.h)}
  if(!running){ctx.fillStyle='#fff';ctx.font='20px monospace';ctx.textAlign='center';ctx.fillText('GAME OVER — Click to restart',W/2,H/2)}}
function loop(){update();draw();requestAnimationFrame(loop)}
c.addEventListener('mousemove',e=>{const rect=c.getBoundingClientRect();paddle.x=e.clientX-rect.left-paddle.w/2;paddle.x=Math.max(0,Math.min(W-paddle.w,paddle.x))});
c.addEventListener('click',()=>{if(!running){running=true;lives=3;score=0;document.getElementById('lives').textContent=3;document.getElementById('score').textContent=0;initBricks();reset()}});
initBricks();loop();
</script></body></html>
