</style></head><body>
<div class="app">
<h1>Unit Converter</h1>
<div class="tabs"><button class="tab active" onclick="setCategory('length',this)">Length</button><button class="tab" onclick="setCategory('weight',this)">Weight</button><button class="tab" onclick="setCategory('temp',this)">Temp</button></div>
<div class="group"><label>From</label><select id="fromUnit" onchange="convert()"></select></div>
<div class="group"><label>Value</label><input type="number" id="val" value="1" oninput="convert()"></div>
<button class="swap" onclick="swap()">↕ Swap</button>
<div class="group"><label>To</label><select id="toUnit" onchange="convert()"></select></div>
<div class="result" id="result">—</div>
</div>
<script>
const units={length:{m:1,km:1000,cm:0.01,mm:0.001,mi:1609.344,ft:0.3048,in:0.0254,yd:0.9144},weight:{kg:1,g:0.001,mg:0.000001,lb:0.453592,oz:0.0283495,ton:1000},temp:['C','F','K']};
let category='length';
function setCategory(cat,el){category=cat;document.querySelectorAll('.tab').forEach(t=>t.classList.remove('active'));el.classList.add('active');buildSelects();convert()}
function buildSelects(){const keys=category==='temp'?units.temp:Object.keys(units[category]);
  const opts=keys.map(k=>`<option value="${k}">${k}</option>`).join('');
  document.getElementById('fromUnit').innerHTML=opts;document.getElementById('toUnit').innerHTML=opts;
  if(keys.length>1)document.getElementById('toUnit').selectedIndex=1}
function convert(){const from=document.getElementById('fromUnit').value,to=document.getElementById('toUnit').value,val=parseFloat(document.getElementById('val').value)||0;
  let result;
  if(category==='temp'){if(from===to)result=val;else if(from==='C'&&to==='F')result=val*9/5+32;else if(from==='F'&&to==='C')result=(val-32)*5/9;
    else if(from==='C'&&to==='K')result=val+273.15;else if(from==='K'&&to==='C')result=val-273.15;
    else if(from==='F'&&to==='K')result=(val-32)*5/9+273.15;else result=(val-273.15)*9/5+32}
  else{const base=val*units[category][from];result=base/units[category][to]}
  document.getElementById('result').textContent=result.toFixed(4).replace(/\.?0+$/,'')+' '+to}
function swap(){const f=document.getElementById('fromUnit'),t=document.getElementById('toUnit');const tmp=f.value;f.value=t.value;t.value=tmp;convert()}
buildSelects();convert();
</script></body></html>
