</style></head><body>
<h1>Minesweeper</h1>
<div id="info">Left-click: reveal | Right-click: flag | Mines: <span id="mineCount">15</span></div>
<div class="grid" id="grid" oncontextmenu="return false"></div>
<div id="msg"></div>
<button onclick="init()">New Game</button>
<script>
const ROWS=10,COLS=10,MINES=15;let grid,revealed,flagged,gameOver,firstClick;
function init(){grid=Array(ROWS).fill(null).map(()=>Array(COLS).fill(0));revealed=Array(ROWS).fill(null).map(()=>Array(COLS).fill(false));
  flagged=Array(ROWS).fill(null).map(()=>Array(COLS).fill(false));gameOver=false;firstClick=true;
  document.getElementById('msg').textContent='';document.getElementById('mineCount').textContent=MINES;render()}
function placeMines(sr,sc){let placed=0;while(placed<MINES){const r=Math.floor(Math.random()*ROWS),c=Math.floor(Math.random()*COLS);
  if(grid[r][c]===-1||((Math.abs(r-sr)<=1)&&(Math.abs(c-sc)<=1)))continue;grid[r][c]=-1;placed++}
  for(let r=0;r<ROWS;r++)for(let c=0;c<COLS;c++){if(grid[r][c]===-1)continue;let n=0;
    for(let dr=-1;dr<=1;dr++)for(let dc=-1;dc<=1;dc++){const nr=r+dr,nc=c+dc;if(nr>=0&&nr<ROWS&&nc>=0&&nc<COLS&&grid[nr][nc]===-1)n++}grid[r][c]=n}}
function reveal(r,c){if(r<0||r>=ROWS||c<0||c>=COLS||revealed[r][c]||flagged[r][c]||gameOver)return;
  revealed[r][c]=true;if(grid[r][c]===-1){gameOver=true;revealAll();document.getElementById('msg').textContent='💥 Game Over!';return}
  if(grid[r][c]===0){for(let dr=-1;dr<=1;dr++)for(let dc=-1;dc<=1;dc++)reveal(r+dr,c+dc)}checkWin()}
function revealAll(){for(let r=0;r<ROWS;r++)for(let c=0;c<COLS;c++)revealed[r][c]=true;render()}
function checkWin(){let unrevealed=0;for(let r=0;r<ROWS;r++)for(let c=0;c<COLS;c++){if(!revealed[r][c]&&grid[r][c]!==-1)unrevealed++}
  if(unrevealed===0){gameOver=true;document.getElementById('msg').textContent='🎉 You Win!'}render()}
function render(){const el=document.getElementById('grid');el.style.gridTemplateColumns=`repeat(${COLS},32px)`;el.innerHTML='';
  for(let r=0;r<ROWS;r++)for(let c=0;c<COLS;c++){const cell=document.createElement('div');
    cell.className='cell'+(revealed[r][c]?(grid[r][c]===-1?' mine':' revealed'):' hidden')+(flagged[r][c]?' flagged':'');
    if(revealed[r][c]&&grid[r][c]>0){cell.textContent=grid[r][c];cell.classList.add('c'+grid[r][c])}
    if(revealed[r][c]&&grid[r][c]===-1)cell.textContent='💣';
    cell.onclick=()=>{if(gameOver||flagged[r][c])return;if(firstClick){firstClick=false;placeMines(r,c)}reveal(r,c);render()};
    cell.oncontextmenu=(e)=>{e.preventDefault();if(gameOver||revealed[r][c])return;flagged[r][c]=!flagged[r][c];render()};el.appendChild(cell)}}
init();
</script></body></html>
```

