This React-like state update doesn't re-render:
```js
function Counter() {
  let count = 0;
  const el = document.getElementById('counter');
  el.innerHTML = `<button id='inc'>Count: ${count}</button>`;
  document.getElementById('inc').onclick = () => { count++; };
}
Counter();
```

The DOM never updates because you set `innerHTML` once and the click handler only mutates a local variable — nothing triggers a re-render.

Fix: call a render function after every state change:

```javascript
function Counter() {
  let count = 0;
  const el = document.getElementById('counter');

  function render() {
    el.innerHTML = `<button id='inc'>Count: ${count}</button>`;
    document.getElementById('inc').onclick = () => { count++; render(); };
  }

  render();
}
Counter();
```

**Why the original fails:** Updating `count++` changes the variable but never re-executes the template. In React this is automatic (setState triggers re-render). In vanilla JS you must manually re-render after state changes.

**Better pattern** for larger apps — a minimal reactive store:

```javascript
function createStore(initial, renderFn) {
  let state = initial;
  function setState(updater) {
    state = typeof updater === 'function' ? updater(state) : updater;
    renderFn(state);
  }
  renderFn(state);
  return setState;
}

const setState = createStore(0, (count) => {
  document.getElementById('counter').innerHTML =
    `<button onclick="increment()">Count: ${count}</button>`;
});

window.increment = () => setState(c => c + 1);
```

Here's Space Invaders with waves and scoring:

```html
<!DOCTYPE html>
<html><head><meta charset="UTF-8"><title>Space Invaders</title><style>
*{margin:0;padding:0}body{background:#000;display:flex;flex-direction:column;align-items:center;justify-content:center;height:100vh;font-family:monospace;color:#0f0}
canvas{border:1px solid #0f0}#ui{margin-top:8px;font-size:13px;display:flex;gap:20px}
</style></head><body>
<canvas id="c" width="400" height="500"></canvas>
<div id="ui"><span>Score: <b id="score">0</b></span><span>Wave: <b id="wave">1</b></span><span>Lives: <b id="lives">3</b></span></div>
<script>
const c=document.getElementById('c'),ctx=c.getContext('2d'),W=c.width,H=c.height;
let player={x:W/2-15,w:30,h:12},bullets=[],enemies=[],eBullets=[],score=0,lives=3,wave=1,keys={},gameOver=false;
function spawnWave(){enemies=[];const rows=3+Math.min(wave,4),cols=8;for(let r=0;r<rows;r++)for(let c2=0;c2<cols;c2++)enemies.push({x:c2*45+30,y:r*35+40,w:28,h:18,alive:true})}
function update(){if(gameOver)return;
  if(keys.ArrowLeft)player.x=Math.max(0,player.x-4);if(keys.ArrowRight)player.x=Math.min(W-player.w,player.x+4);
  bullets.forEach(b=>b.y-=6);bullets=bullets.filter(b=>b.y>0);
  eBullets.forEach(b=>b.y+=3);eBullets=eBullets.filter(b=>b.y<H);
  // Move enemies
  let dx=1+wave*0.3,shift=false;enemies.forEach(e=>{if(!e.alive)return;e.x+=dx;if(e.x>W-e.w||e.x<0)shift=true});
  if(shift)enemies.forEach(e=>{e.y+=15;e.x-=dx*2});
  // Collision: bullet->enemy
  for(const b of bullets){for(const e of enemies){if(!e.alive)continue;if(b.x>e.x&&b.x<e.x+e.w&&b.y>e.y&&b.y<e.y+e.h){e.alive=false;b.y=-10;score++;document.getElementById('score').textContent=score}}}
  // Enemy shoots randomly
  const alive=enemies.filter(e=>e.alive);if(alive.length&&Math.random()<0.02){const e=alive[Math.floor(Math.random()*alive.length)];eBullets.push({x:e.x+e.w/2,y:e.y+e.h})}
  // Collision: eBullet->player
  for(const b of eBullets){if(b.x>player.x&&b.x<player.x+player.w&&b.y>H-30){lives--;document.getElementById('lives').textContent=lives;b.y=H+10;if(lives<=0)gameOver=true}}
  // Next wave
  if(!alive.length){wave++;document.getElementById('wave').textContent=wave;spawnWave()}}
function draw(){ctx.fillStyle='#000';ctx.fillRect(0,0,W,H);
  ctx.fillStyle='#0f0';ctx.fillRect(player.x,H-25,player.w,player.h);
  ctx.fillStyle='#0f0';bullets.forEach(b=>ctx.fillRect(b.x-1,b.y,3,8));
  ctx.fillStyle='#f00';eBullets.forEach(b=>ctx.fillRect(b.x-1,b.y,3,8));
  ctx.fillStyle='#0f0';enemies.forEach(e=>{if(!e.alive)return;ctx.fillRect(e.x,e.y,e.w,e.h)});
  if(gameOver){ctx.fillStyle='#f00';ctx.font='24px monospace';ctx.textAlign='center';ctx.fillText('GAME OVER',W/2,H/2)}}
function loop(){update();draw();requestAnimationFrame(loop)}
document.addEventListener('keydown',e=>{keys[e.key]=true;if(e.key===' '){e.preventDefault();if(!gameOver)bullets.push({x:player.x+player.w/2,y:H-30})}});
document.addEventListener('keyup',e=>keys[e.key]=false);
spawnWave();loop();
</script></body></html>
