</style></head><body>
<div class="app">
<h1>Notes</h1>
<input class="search" placeholder="Search notes..." oninput="render()" id="search">
<div class="tags-row" id="tagsRow"></div>
<button class="add-btn" onclick="toggleForm()">+ New Note</button>
<div class="note-form" id="form">
  <input id="nTitle" placeholder="Title"><textarea id="nBody" placeholder="Write your note..."></textarea>
  <input id="nTags" placeholder="Tags (comma separated)">
  <div class="btns"><button class="btn-save" onclick="saveNote()">Save</button><button class="btn-cancel" onclick="toggleForm()">Cancel</button></div>
</div>
<div class="notes" id="notes"></div>
</div>
<script>
let notes=JSON.parse(localStorage.getItem('notes')||'[]'),activeTag='';
function save(){localStorage.setItem('notes',JSON.stringify(notes))}
function toggleForm(){document.getElementById('form').classList.toggle('open')}
function saveNote(){const title=document.getElementById('nTitle').value.trim(),body=document.getElementById('nBody').value.trim(),tags=document.getElementById('nTags').value.split(',').map(t=>t.trim()).filter(Boolean);
  if(!title)return;notes.unshift({id:Date.now(),title,body,tags,date:new Date().toLocaleDateString()});save();render();toggleForm();
  document.getElementById('nTitle').value='';document.getElementById('nBody').value='';document.getElementById('nTags').value=''}
function delNote(id){notes=notes.filter(n=>n.id!==id);save();render()}
function render(){const q=document.getElementById('search').value.toLowerCase();
  const allTags=[...new Set(notes.flatMap(n=>n.tags))];document.getElementById('tagsRow').innerHTML=allTags.map(t=>`<button class="tag-filter${t===activeTag?' active':''}" onclick="filterTag('${t}')">${t}</button>`).join('');
  let filtered=notes;if(q)filtered=filtered.filter(n=>n.title.toLowerCase().includes(q)||n.body.toLowerCase().includes(q)||n.tags.some(t=>t.toLowerCase().includes(q)));
  if(activeTag)filtered=filtered.filter(n=>n.tags.includes(activeTag));
  document.getElementById('notes').innerHTML=filtered.map(n=>`<div class="note"><div class="note-title">${n.title}</div><div class="note-body">${n.body.slice(0,150)}${n.body.length>150?'...':''}</div><div class="note-footer">${n.tags.map(t=>`<span class="note-tag">${t}</span>`).join('')}<span class="note-date">${n.date}</span><button class="note-del" onclick="delNote(${n.id})">\u00d7</button></div></div>`).join('')||'<p style="text-align:center;color:#475569;padding:20px">No notes found</p>'}
window.filterTag=function(t){activeTag=activeTag===t?'':t;render()};render();
</script></body></html>
