```html
<!DOCTYPE html>
<html><head><meta charset="UTF-8"><title>Gallery</title><style>
*{margin:0;padding:0;box-sizing:border-box}
body{background:#0a0a0a;color:#fff;font-family:system-ui;padding:24px}
h1{text-align:center;font-size:22px;margin-bottom:24px;color:#e2e8f0}
.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:8px;max-width:900px;margin:0 auto}
.grid-item{aspect-ratio:1;border-radius:8px;overflow:hidden;cursor:pointer;position:relative;transition:transform .2s}
.grid-item:hover{transform:scale(1.03);z-index:1}
.grid-item img{width:100%;height:100%;object-fit:cover}
.lightbox{position:fixed;inset:0;background:rgba(0,0,0,.95);z-index:1000;display:none;align-items:center;justify-content:center;flex-direction:column;padding:20px}
.lightbox.open{display:flex}
.lightbox img{max-width:90vw;max-height:80vh;border-radius:8px;object-fit:contain}
.lightbox-close{position:absolute;top:20px;right:24px;background:none;border:none;color:#fff;font-size:32px;cursor:pointer}
.lightbox-nav{position:absolute;top:50%;transform:translateY(-50%);background:rgba(255,255,255,.1);border:none;color:#fff;font-size:24px;padding:12px 16px;cursor:pointer;border-radius:8px}
.lightbox-nav:hover{background:rgba(255,255,255,.2)}
.lightbox-prev{left:20px}
.lightbox-next{right:20px}
.lightbox-info{margin-top:12px;font-size:13px;color:#94a3b8}
</style></head><body>
<h1>Gallery</h1>
<div class="grid" id="grid"></div>
<div class="lightbox" id="lightbox" onclick="if(event.target===this)closeLightbox()">
  <button class="lightbox-close" onclick="closeLightbox()">\u00d7</button>
  <button class="lightbox-nav lightbox-prev" onclick="navigate(-1)">\u2190</button>
  <button class="lightbox-nav lightbox-next" onclick="navigate(1)">\u2192</button>
  <img id="lbImg" src="">
  <div class="lightbox-info" id="lbInfo"></div>
</div>
<script>
const images=[];for(let i=1;i<=12;i++){const hue=i*30;images.push({url:`https://placehold.co/600x600/${hslToHex(hue,70,40)}/${hslToHex(hue,70,80)}?text=Photo+${i}`,title:`Photo ${i}`})}
function hslToHex(h,s,l){s/=100;l/=100;const a=s*Math.min(l,1-l);const f=n=>{const k=(n+h/30)%12;return Math.round((l-a*Math.max(Math.min(k-3,9-k,1),-1))*255).toString(16).padStart(2,'0')};return f(0)+f(8)+f(4)}
const grid=document.getElementById('grid');
images.forEach((img,i)=>{const div=document.createElement('div');div.className='grid-item';
  div.innerHTML=`<img src="${img.url}" alt="${img.title}" loading="lazy">`;div.onclick=()=>openLightbox(i);grid.appendChild(div)});
let currentIdx=0;
function openLightbox(i){currentIdx=i;document.getElementById('lbImg').src=images[i].url;document.getElementById('lbInfo').textContent=`${images[i].title} (${i+1}/${images.length})`;
  document.getElementById('lightbox').classList.add('open');document.body.style.overflow='hidden'}
function closeLightbox(){document.getElementById('lightbox').classList.remove('open');document.body.style.overflow=''}
function navigate(dir){currentIdx=(currentIdx+dir+images.length)%images.length;openLightbox(currentIdx)}
document.addEventListener('keydown',e=>{if(!document.getElementById('lightbox').classList.contains('open'))return;if(e.key==='Escape')closeLightbox();if(e.key==='ArrowLeft')navigate(-1);if(e.key==='ArrowRight')navigate(1)});
</script></body></html>
