Here's Flappy Bird with pipes, score, and gravity:

```html
<!DOCTYPE html>
<html><head><meta charset="UTF-8"><title>Flappy</title><style>
*{margin:0;padding:0}body{background:#70c5ce;display:flex;flex-direction:column;align-items:center;justify-content:center;height:100vh;font-family:monospace}
canvas{border:3px solid #543847;border-radius:4px}
#ui{margin-top:8px;font-size:14px;color:#543847;font-weight:700}
</style></head><body>
<canvas id="c" width="320" height="480"></canvas>
<div id="ui">Tap or Space to start</div>
<script>
const c=document.getElementById('c'),ctx=c.getContext('2d'),W=c.width,H=c.height;
const GRAVITY=0.4,FLAP=-7,PIPE_W=52,GAP=130,PIPE_SPEED=2.5;
let bird={x:80,y:H/2,vy:0,r:14},pipes=[],score=0,best=0,state='idle',frame=0;
function reset(){bird.y=H/2;bird.vy=0;pipes=[];score=0;frame=0}
function addPipe(){const gapY=80+Math.random()*(H-GAP-160);pipes.push({x:W,top:gapY,bot:gapY+GAP})}
function update(){if(state!=='playing')return;bird.vy+=GRAVITY;bird.y+=bird.vy;frame++;
  if(frame%90===0)addPipe();
  pipes.forEach(p=>p.x-=PIPE_SPEED);pipes=pipes.filter(p=>p.x+PIPE_W>0);
  for(const p of pipes){if(bird.x+bird.r>p.x&&bird.x-bird.r<p.x+PIPE_W){if(bird.y-bird.r<p.top||bird.y+bird.r>p.bot){die();return}}
    if(!p.scored&&p.x+PIPE_W<bird.x){p.scored=true;score++}}
  if(bird.y+bird.r>H||bird.y-bird.r<0)die()}
function die(){state='dead';if(score>best)best=score;document.getElementById('ui').textContent=`Score: ${score} | Best: ${best} | Tap to restart`}
function draw(){ctx.fillStyle='#70c5ce';ctx.fillRect(0,0,W,H);
  ctx.fillStyle='#dec369';ctx.fillRect(0,H-40,W,40);ctx.fillStyle='#8ec63f';ctx.fillRect(0,H-44,W,6);
  pipes.forEach(p=>{ctx.fillStyle='#73bf2e';ctx.fillRect(p.x,0,PIPE_W,p.top);ctx.fillRect(p.x,p.bot,PIPE_W,H-p.bot);
    ctx.fillStyle='#5ca51c';ctx.fillRect(p.x-3,p.top-16,PIPE_W+6,16);ctx.fillRect(p.x-3,p.bot,PIPE_W+6,16)});
  ctx.fillStyle='#f7dc6f';ctx.beginPath();ctx.arc(bird.x,bird.y,bird.r,0,Math.PI*2);ctx.fill();
  ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(bird.x+5,bird.y-3,5,0,Math.PI*2);ctx.fill();
  ctx.fillStyle='#000';ctx.beginPath();ctx.arc(bird.x+6,bird.y-3,2.5,0,Math.PI*2);ctx.fill();
  ctx.fillStyle='#e74c3c';ctx.fillRect(bird.x+bird.r-2,bird.y+2,8,4);
  ctx.fillStyle='#fff';ctx.font='24px monospace';ctx.textAlign='center';ctx.fillText(score,W/2,40);
  if(state==='idle'){ctx.font='14px monospace';ctx.fillText('TAP TO START',W/2,H/2)}}
function flap(){if(state==='idle'){state='playing';reset();addPipe()}
  else if(state==='dead'){state='playing';reset();addPipe()}
  if(state==='playing')bird.vy=FLAP}
function loop(){update();draw();requestAnimationFrame(loop)}loop();
document.addEventListener('keydown',e=>{if(e.code==='Space'){e.preventDefault();flap()}});
c.addEventListener('click',flap);c.addEventListener('touchstart',e=>{e.preventDefault();flap()});
</script></body></html>
```

