  const balances={};people.forEach(p=>balances[p]=0);expenses.forEach(e=>balances[e.by]+=e.amt);people.forEach(p=>balances[p]-=perPerson);
  const debtors=people.filter(p=>balances[p]<-0.01).map(p=>({name:p,amt:-balances[p]})).sort((a,b)=>b.amt-a.amt);
  const creditors=people.filter(p=>balances[p]>0.01).map(p=>({name:p,amt:balances[p]})).sort((a,b)=>b.amt-a.amt);
  const result=[];let i=0,j=0;
  while(i<debtors.length&&j<creditors.length){const pay=Math.min(debtors[i].amt,creditors[j].amt);
    result.push({from:debtors[i].name,to:creditors[j].name,amt:pay.toFixed(2)});debtors[i].amt-=pay;creditors[j].amt-=pay;
