function render(){document.getElementById('people').innerHTML=people.map(p=>`<span class="person-chip">${p}<span class="x" onclick="removePerson('${p}')">x</span></span>`).join('');
  document.getElementById('expBy').innerHTML=people.map(p=>`<option>${p}</option>`).join('');
