  const s=calcSettlements();document.getElementById('settlements').innerHTML=s.length?s.map(x=>`<div class="settlement"><span>${x.from}</span> <span class="arrow">pays $${x.amt} to</span> <span>${x.to}</span></div>`).join(''):'<p style="color:#475569;font-size:12px">Add people and expenses to see settlements</p>'}
render();
