Fix this async code that has a race condition:
```js
let cache = {};
async function getData(key) {
  if (cache[key]) return cache[key];
  const data = await fetch(`/api/${key}`).then(r => r.json());
  cache[key] = data;
  return data;
}
// Called multiple times simultaneously:
getData('users'); getData('users'); getData('users');
```

The race: 3 calls check `cache['users']` simultaneously, all see it empty, all fire 3 identical fetches. Only the first fetch is needed.

Fix: cache the **Promise**, not the result:

```javascript
let cache = {};

async function getData(key) {
  if (cache[key]) return cache[key];

  // Store the promise immediately — subsequent calls await the same one
  cache[key] = fetch(`/api/${key}`).then(r => r.json());
  return cache[key];
}

// Now all 3 calls share one fetch:
getData('users'); getData('users'); getData('users');
// Only 1 network request fires
```

**Why this works:** The second and third calls see `cache['users']` already set (to a pending Promise), so they `return` the same Promise. All three await the same result.

**With error handling + TTL:**

```javascript
const cache = new Map();
const TTL = 60_000; // 1 minute

async function getData(key) {
  const entry = cache.get(key);
  if (entry && Date.now() - entry.time < TTL) {
    return entry.promise;
  }

  const promise = fetch(`/api/${key}`)
    .then(r => {
      if (!r.ok) throw new Error(`HTTP ${r.status}`);
      return r.json();
    })
    .catch(err => {
      cache.delete(key); // Don't cache errors
      throw err;
    });

  cache.set(key, { promise, time: Date.now() });
  return promise;
}
```

Key insight: **cache Promises, not resolved values** — this is the standard deduplication pattern for concurrent async calls.

Here's a complete MERN e-commerce — backend (Express + MongoDB) and frontend (React):

## Backend: server.js
```javascript
const express = require('express');
const mongoose = require('mongoose');
const cors = require('cors');
const app = express();
app.use(cors());
app.use(express.json());

mongoose.connect(process.env.MONGO_URI || 'mongodb://localhost:27017/shop');

const ProductSchema = new mongoose.Schema({
  name: String, price: Number, image: String, description: String, stock: Number
});
const Product = mongoose.model('Product', ProductSchema);

const OrderSchema = new mongoose.Schema({
  items: [{ productId: String, name: String, price: Number, qty: Number }],
  total: Number, status: { type: String, default: 'pending' }, createdAt: { type: Date, default: Date.now }
});
const Order = mongoose.model('Order', OrderSchema);

// Seed products
app.get('/api/seed', async (req, res) => {
  await Product.deleteMany({});
  await Product.insertMany([
    { name: 'Wireless Headphones', price: 79.99, image: 'https://placehold.co/300x300/1a1a2e/fff?text=Headphones', description: 'Premium noise-cancelling', stock: 50 },
    { name: 'Mechanical Keyboard', price: 129.99, image: 'https://placehold.co/300x300/2d1b69/fff?text=Keyboard', description: 'Cherry MX switches, RGB', stock: 30 },
    { name: 'USB-C Hub', price: 49.99, image: 'https://placehold.co/300x300/1b4d3e/fff?text=Hub', description: '7-in-1, 4K HDMI', stock: 100 },
    { name: 'Webcam 4K', price: 99.99, image: 'https://placehold.co/300x300/4a1942/fff?text=Webcam', description: 'Auto-focus, low light', stock: 25 },
    { name: 'Monitor Stand', price: 39.99, image: 'https://placehold.co/300x300/0f3460/fff?text=Stand', description: 'Adjustable, cable management', stock: 75 },
    { name: 'Desk Lamp', price: 34.99, image: 'https://placehold.co/300x300/3d0066/fff?text=Lamp', description: 'LED, 5 brightness levels', stock: 60 },
  ]);
  res.json({ message: 'Seeded 6 products' });
});

app.get('/api/products', async (req, res) => {
  const products = await Product.find();
  res.json(products);
});

app.get('/api/products/:id', async (req, res) => {
  const product = await Product.findById(req.params.id);
  if (!product) return res.status(404).json({ error: 'Not found' });
  res.json(product);
});

app.post('/api/orders', async (req, res) => {
  const { items } = req.body;
  if (!items || !items.length) return res.status(400).json({ error: 'No items' });
  const total = items.reduce((s, i) => s + i.price * i.qty, 0);
  const order = await Order.create({ items, total });
  // Decrement stock
  for (const item of items) {
    await Product.findByIdAndUpdate(item.productId, { $inc: { stock: -item.qty } });
  }
  res.status(201).json(order);
});

app.get('/api/orders', async (req, res) => {
  const orders = await Order.find().sort({ createdAt: -1 });
  res.json(orders);
});

app.listen(5000, () => console.log('Server on :5000'));
```

