    setCart(prev => {
      const existing = prev.find(i => i.productId === product._id);
      if (existing) return prev.map(i => i.productId === product._id ? { ...i, qty: i.qty + 1 } : i);
      return [...prev, { productId: product._id, name: product.name, price: product.price, qty: 1 }];
    });
  };

  const removeFromCart = (id) => setCart(prev => prev.filter(i => i.productId !== id));
  const updateQty = (id, qty) => setCart(prev => prev.map(i => i.productId === id ? { ...i, qty: Math.max(1, qty) } : i));
  const total = cart.reduce((s, i) => s + i.price * i.qty, 0);

  const checkout = async () => {
    await fetch(`${API}/orders`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ items: cart }) });
    setCart([]); setView('success');
  };

  if (view === 'success') return (
    <div style={{ textAlign: 'center', padding: 60 }}>
      <h2>Order Placed!</h2>
      <p>Your items are on the way.</p>
      <button onClick={() => setView('shop')}>Continue Shopping</button>
    </div>
  );

  if (view === 'cart') return (
    <div style={{ padding: 24, maxWidth: 600, margin: '0 auto' }}>
      <h2>Cart ({cart.length} items)</h2>
      {cart.map(item => (
        <div key={item.productId} style={{ display: 'flex', gap: 12, padding: 12, borderBottom: '1px solid #eee' }}>
          <span style={{ flex: 1 }}>{item.name}</span>
          <input type="number" value={item.qty} onChange={e => updateQty(item.productId, +e.target.value)} style={{ width: 50 }} />
          <span>${(item.price * item.qty).toFixed(2)}</span>
          <button onClick={() => removeFromCart(item.productId)}>X</button>
        </div>
      ))}
      <div style={{ marginTop: 16, fontSize: 20, fontWeight: 600 }}>Total: ${total.toFixed(2)}</div>
      <button onClick={checkout} disabled={!cart.length} style={{ marginTop: 12, padding: '12px 24px', background: '#4ade80', border: 'none', borderRadius: 8, fontWeight: 600, cursor: 'pointer' }}>Place Order</button>
      <button onClick={() => setView('shop')} style={{ marginLeft: 8 }}>Back to Shop</button>
    </div>
  );

  return (
    <div style={{ padding: 24 }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 24 }}>
        <h1>Om Shop</h1>
        <button onClick={() => setView('cart')}>Cart ({cart.length})</button>
      </div>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(250px, 1fr))', gap: 16 }}>
        {products.map(p => (
          <div key={p._id} style={{ border: '1px solid #eee', borderRadius: 12, overflow: 'hidden' }}>
            <img src={p.image} alt={p.name} style={{ width: '100%', height: 200, objectFit: 'cover' }} />
            <div style={{ padding: 12 }}>
              <h3>{p.name}</h3>
              <p style={{ color: '#666', fontSize: 13 }}>{p.description}</p>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginTop: 8 }}>
                <span style={{ fontSize: 20, fontWeight: 600 }}>${p.price}</span>
                <button onClick={() => addToCart(p)} style={{ padding: '8px 16px', background: '#3b82f6', color: '#fff', border: 'none', borderRadius: 6, cursor: 'pointer' }}>Add to Cart</button>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

export default App;
