## Backend: server.js (Express + MongoDB)
```javascript
const express = require('express');
const mongoose = require('mongoose');
const cors = require('cors');
const app = express();
app.use(cors());
app.use(express.json());

mongoose.connect(process.env.MONGO_URI || 'mongodb://localhost:27017/taskmanager');

const TaskSchema = new mongoose.Schema({
  title: { type: String, required: true },
  description: String,
  status: { type: String, enum: ['todo', 'in_progress', 'done'], default: 'todo' },
  priority: { type: String, enum: ['low', 'medium', 'high'], default: 'medium' },
  dueDate: Date,
  createdAt: { type: Date, default: Date.now },
  updatedAt: { type: Date, default: Date.now }
});
TaskSchema.pre('save', function() { this.updatedAt = Date.now() });
const Task = mongoose.model('Task', TaskSchema);

// CRUD endpoints
app.get('/api/tasks', async (req, res) => {
  const { status, priority, sort = '-createdAt' } = req.query;
  const filter = {};
  if (status) filter.status = status;
  if (priority) filter.priority = priority;
  const tasks = await Task.find(filter).sort(sort);
  res.json(tasks);
});

app.get('/api/tasks/:id', async (req, res) => {
  const task = await Task.findById(req.params.id);
  if (!task) return res.status(404).json({ error: 'Task not found' });
  res.json(task);
});

app.post('/api/tasks', async (req, res) => {
  const task = await Task.create(req.body);
  res.status(201).json(task);
});

app.put('/api/tasks/:id', async (req, res) => {
  const task = await Task.findByIdAndUpdate(req.params.id, { ...req.body, updatedAt: Date.now() }, { new: true });
  if (!task) return res.status(404).json({ error: 'Task not found' });
  res.json(task);
});

app.patch('/api/tasks/:id/status', async (req, res) => {
  const task = await Task.findByIdAndUpdate(req.params.id, { status: req.body.status, updatedAt: Date.now() }, { new: true });
  if (!task) return res.status(404).json({ error: 'Task not found' });
  res.json(task);
});

app.delete('/api/tasks/:id', async (req, res) => {
  await Task.findByIdAndDelete(req.params.id);
  res.json({ message: 'Deleted' });
});

app.get('/api/tasks/stats/summary', async (req, res) => {
  const [todo, inProgress, done] = await Promise.all([
    Task.countDocuments({ status: 'todo' }),
    Task.countDocuments({ status: 'in_progress' }),
    Task.countDocuments({ status: 'done' }),
  ]);
  res.json({ todo, inProgress, done, total: todo + inProgress + done });
});

app.listen(5000, () => console.log('API running on :5000'));
```

## Angular Frontend: task.service.ts
```typescript
import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable } from 'rxjs';

export interface Task {
  _id?: string;
  title: string;
  description?: string;
  status: 'todo' | 'in_progress' | 'done';
  priority: 'low' | 'medium' | 'high';
  dueDate?: string;
  createdAt?: string;
}

@Injectable({ providedIn: 'root' })
export class TaskService {
  private api = 'http://localhost:5000/api/tasks';

  constructor(private http: HttpClient) {}

  getTasks(filters?: { status?: string; priority?: string }): Observable<Task[]> {
    const params: any = {};
    if (filters?.status) params.status = filters.status;
    if (filters?.priority) params.priority = filters.priority;
    return this.http.get<Task[]>(this.api, { params });
  }

  createTask(task: Partial<Task>): Observable<Task> {
    return this.http.post<Task>(this.api, task);
  }

  updateTask(id: string, task: Partial<Task>): Observable<Task> {
    return this.http.put<Task>(`${this.api}/${id}`, task);
  }

  updateStatus(id: string, status: string): Observable<Task> {
    return this.http.patch<Task>(`${this.api}/${id}/status`, { status });
  }

  deleteTask(id: string): Observable<any> {
    return this.http.delete(`${this.api}/${id}`);
  }

  getStats(): Observable<{ todo: number; inProgress: number; done: number; total: number }> {
    return this.http.get<any>(`${this.api}/stats/summary`);
  }
}
