import { Component, OnInit } from '@angular/core';
import { TaskService, Task } from './task.service';

@Component({
  selector: 'app-task-board',
  template: `
    <div class="board">
      <header>
        <h1>Task Manager</h1>
        <div class="stats">
          <span class="badge todo">Todo: {{stats.todo}}</span>
          <span class="badge progress">In Progress: {{stats.inProgress}}</span>
          <span class="badge done">Done: {{stats.done}}</span>
        </div>
      </header>
      <div class="add-form">
        <input [(ngModel)]="newTask.title" placeholder="Task title" />
        <select [(ngModel)]="newTask.priority">
          <option value="low">Low</option>
          <option value="medium">Medium</option>
          <option value="high">High</option>
        </select>
        <button (click)="addTask()">Add Task</button>
      </div>
      <div class="columns">
        <div class="column" *ngFor="let col of columns">
          <h3>{{col.label}} ({{getTasksByStatus(col.status).length}})</h3>
          <div class="task-card" *ngFor="let task of getTasksByStatus(col.status)"
               [class]="'priority-' + task.priority">
            <div class="task-title">{{task.title}}</div>
            <div class="task-meta">
              <span class="priority">{{task.priority}}</span>
              <span class="date">{{task.createdAt | date:'short'}}</span>
            </div>
            <div class="task-actions">
              <button *ngIf="task.status !== 'done'" (click)="moveForward(task)">→</button>
              <button *ngIf="task.status !== 'todo'" (click)="moveBack(task)">←</button>
              <button (click)="delete(task._id!)">×</button>
            </div>
          </div>
        </div>
      </div>
    </div>
  `
})
export class TaskBoardComponent implements OnInit {
  tasks: Task[] = [];
  stats = { todo: 0, inProgress: 0, done: 0, total: 0 };
  newTask = { title: '', priority: 'medium' as const };
  columns = [
    { status: 'todo', label: 'To Do' },
    { status: 'in_progress', label: 'In Progress' },
    { status: 'done', label: 'Done' }
  ];

  constructor(private taskService: TaskService) {}

  ngOnInit() { this.load(); }

  load() {
    this.taskService.getTasks().subscribe(t => this.tasks = t);
    this.taskService.getStats().subscribe(s => this.stats = s);
  }

  getTasksByStatus(status: string) { return this.tasks.filter(t => t.status === status); }

  addTask() {
    if (!this.newTask.title) return;
    this.taskService.createTask({ ...this.newTask, status: 'todo' }).subscribe(() => {
      this.newTask.title = '';
      this.load();
    });
  }

  moveForward(task: Task) {
    const next = task.status === 'todo' ? 'in_progress' : 'done';
    this.taskService.updateStatus(task._id!, next).subscribe(() => this.load());
  }

  moveBack(task: Task) {
    const prev = task.status === 'done' ? 'in_progress' : 'todo';
    this.taskService.updateStatus(task._id!, prev).subscribe(() => this.load());
  }

  delete(id: string) { this.taskService.deleteTask(id).subscribe(() => this.load()); }
}
