  description: string;
  category: string;
  date: string;
}

const CATEGORIES = ['Food', 'Transport', 'Shopping', 'Bills', 'Entertainment', 'Health', 'Other'];
const CATEGORY_COLORS: Record<string, string> = {
  Food: '#4ade80', Transport: '#60a5fa', Shopping: '#f97316',
  Bills: '#ef4444', Entertainment: '#a78bfa', Health: '#f472b6', Other: '#94a3b8'
};

export default function App() {
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [modalVisible, setModalVisible] = useState(false);
  const [amount, setAmount] = useState('');
  const [description, setDescription] = useState('');
  const [category, setCategory] = useState('Food');

  useEffect(() => { loadExpenses(); }, []);

  const loadExpenses = async () => {
    const data = await AsyncStorage.getItem('expenses');
    if (data) setExpenses(JSON.parse(data));
  };

  const saveExpenses = async (updated: Expense[]) => {
    setExpenses(updated);
    await AsyncStorage.setItem('expenses', JSON.stringify(updated));
  };

  const addExpense = () => {
    if (!amount || !description) return;
    const expense: Expense = {
      id: Date.now().toString(),
      amount: parseFloat(amount),
      description,
      category,
      date: new Date().toISOString(),
    };
    saveExpenses([expense, ...expenses]);
    setAmount(''); setDescription(''); setModalVisible(false);
  };

  const deleteExpense = (id: string) => {
    saveExpenses(expenses.filter(e => e.id !== id));
  };

  const total = expenses.reduce((s, e) => s + e.amount, 0);
  const thisMonth = expenses.filter(e => new Date(e.date).getMonth() === new Date().getMonth());
  const monthTotal = thisMonth.reduce((s, e) => s + e.amount, 0);

  const categoryTotals = CATEGORIES.map(cat => ({
    name: cat,
    total: thisMonth.filter(e => e.category === cat).reduce((s, e) => s + e.amount, 0)
  })).filter(c => c.total > 0).sort((a, b) => b.total - a.total);

  return (
    <SafeAreaView style={styles.container}>
      <View style={styles.header}>
        <Text style={styles.title}>Expenses</Text>
        <TouchableOpacity style={styles.addBtn} onPress={() => setModalVisible(true)}>
          <Text style={styles.addBtnText}>+ Add</Text>
        </TouchableOpacity>
      </View>

      <View style={styles.summary}>
        <View style={styles.summaryCard}>
          <Text style={styles.summaryLabel}>This Month</Text>
          <Text style={styles.summaryAmount}>${monthTotal.toFixed(2)}</Text>
        </View>
        <View style={styles.summaryCard}>
          <Text style={styles.summaryLabel}>All Time</Text>
          <Text style={styles.summaryAmount}>${total.toFixed(2)}</Text>
        </View>
      </View>

      {categoryTotals.length > 0 && (
        <View style={styles.chart}>
          {categoryTotals.map(cat => (
            <View key={cat.name} style={styles.barRow}>
              <Text style={styles.barLabel}>{cat.name}</Text>
              <View style={styles.barBg}>
                <View style={[styles.barFill, { width: `${(cat.total / monthTotal) * 100}%`, backgroundColor: CATEGORY_COLORS[cat.name] }]} />
              </View>
              <Text style={styles.barAmount}>${cat.total.toFixed(0)}</Text>
            </View>
          ))}
        </View>
      )}

      <FlatList
        data={expenses.slice(0, 50)}
        keyExtractor={item => item.id}
        renderItem={({ item }) => (
          <TouchableOpacity style={styles.expense} onLongPress={() => deleteExpense(item.id)}>
            <View style={[styles.dot, { backgroundColor: CATEGORY_COLORS[item.category] }]} />
            <View style={styles.expInfo}>
              <Text style={styles.expDesc}>{item.description}</Text>
              <Text style={styles.expMeta}>{item.category} • {new Date(item.date).toLocaleDateString()}</Text>
            </View>
            <Text style={styles.expAmount}>-${item.amount.toFixed(2)}</Text>
          </TouchableOpacity>
        )}
      />

      <Modal visible={modalVisible} animationType="slide" transparent>
        <View style={styles.modalOverlay}>
          <View style={styles.modal}>
            <Text style={styles.modalTitle}>Add Expense</Text>
            <TextInput style={styles.input} placeholder="Amount" keyboardType="numeric" value={amount} onChangeText={setAmount} placeholderTextColor="#666" />
            <TextInput style={styles.input} placeholder="Description" value={description} onChangeText={setDescription} placeholderTextColor="#666" />
            <View style={styles.categories}>
              {CATEGORIES.map(cat => (
                <TouchableOpacity key={cat} style={[styles.catBtn, category === cat && styles.catBtnActive]} onPress={() => setCategory(cat)}>
                  <Text style={[styles.catText, category === cat && styles.catTextActive]}>{cat}</Text>
                </TouchableOpacity>
              ))}
            </View>
            <TouchableOpacity style={styles.saveBtn} onPress={addExpense}>
              <Text style={styles.saveBtnText}>Save Expense</Text>
            </TouchableOpacity>
            <TouchableOpacity onPress={() => setModalVisible(false)}>
              <Text style={styles.cancelText}>Cancel</Text>
            </TouchableOpacity>
          </View>
        </View>
      </Modal>
    </SafeAreaView>
  );
}

