import React, { useState, useEffect } from 'react';
import { View, Text, TouchableOpacity, StyleSheet, SafeAreaView, Dimensions } from 'react-native';
import AsyncStorage from '@react-native-async-storage/async-storage';

const { width } = Dimensions.get('window');

interface DayData {
  date: string;
  steps: number;
  goal: number;
}

export default function App() {
  const [today, setToday] = useState<DayData>({ date: new Date().toDateString(), steps: 0, goal: 10000 });
  const [week, setWeek] = useState<DayData[]>([]);
  const [streak, setStreak] = useState(0);

  useEffect(() => { loadData(); }, []);

  const loadData = async () => {
    const stored = await AsyncStorage.getItem('fitness_data');
    if (stored) {
      const all: DayData[] = JSON.parse(stored);
      const todayEntry = all.find(d => d.date === new Date().toDateString());
      if (todayEntry) setToday(todayEntry);
      setWeek(all.slice(-7));
      let s = 0;
      for (let i = all.length - 1; i >= 0; i--) {
        if (all[i].steps >= all[i].goal) s++; else break;
      }
      setStreak(s);
    }
  };

  const addSteps = async (amount: number) => {
    const updated = { ...today, steps: today.steps + amount };
    setToday(updated);
    const stored = await AsyncStorage.getItem('fitness_data');
    let all: DayData[] = stored ? JSON.parse(stored) : [];
    const idx = all.findIndex(d => d.date === updated.date);
    if (idx >= 0) all[idx] = updated; else all.push(updated);
    await AsyncStorage.setItem('fitness_data', JSON.stringify(all));
    setWeek(all.slice(-7));
  };

  const progress = Math.min(today.steps / today.goal, 1);
  const circumference = 2 * Math.PI * 90;
  const strokeDashoffset = circumference * (1 - progress);

  const days = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
  const maxSteps = Math.max(...week.map(d => d.steps), today.goal);

  return (
    <SafeAreaView style={styles.container}>
      <Text style={styles.title}>Fitness Tracker</Text>

      <View style={styles.ringContainer}>
        <View style={styles.ring}>
          <View style={styles.ringInner}>
            <Text style={styles.stepsCount}>{today.steps.toLocaleString()}</Text>
            <Text style={styles.stepsLabel}>steps</Text>
            <Text style={styles.goalText}>{today.goal.toLocaleString()} goal</Text>
          </View>
        </View>
        <Text style={styles.percent}>{Math.round(progress * 100)}%</Text>
      </View>

      <View style={styles.statsRow}>
        <View style={styles.stat}>
          <Text style={styles.statVal}>{(today.steps * 0.0008).toFixed(1)}</Text>
          <Text style={styles.statLabel}>km</Text>
        </View>
        <View style={styles.stat}>
          <Text style={styles.statVal}>{Math.round(today.steps * 0.04)}</Text>
          <Text style={styles.statLabel}>kcal</Text>
        </View>
        <View style={styles.stat}>
          <Text style={styles.statVal}>{streak}</Text>
          <Text style={styles.statLabel}>streak</Text>
        </View>
      </View>

      <View style={styles.chart}>
        <Text style={styles.chartTitle}>This Week</Text>
        <View style={styles.bars}>
          {week.map((day, i) => (
            <View key={i} style={styles.barCol}>
              <View style={styles.barBg}>
                <View style={[styles.barFill, {
                  height: `${(day.steps / maxSteps) * 100}%`,
                  backgroundColor: day.steps >= day.goal ? '#4ade80' : '#334155'
                }]} />
              </View>
              <Text style={styles.barDay}>{days[new Date(day.date).getDay()]}</Text>
            </View>
          ))}
        </View>
      </View>

      <View style={styles.buttons}>
        <TouchableOpacity style={styles.btn} onPress={() => addSteps(100)}>
          <Text style={styles.btnText}>+100</Text>
        </TouchableOpacity>
        <TouchableOpacity style={styles.btn} onPress={() => addSteps(500)}>
          <Text style={styles.btnText}>+500</Text>
        </TouchableOpacity>
        <TouchableOpacity style={styles.btn} onPress={() => addSteps(1000)}>
          <Text style={styles.btnText}>+1000</Text>
        </TouchableOpacity>
        <TouchableOpacity style={[styles.btn, styles.btnWalk]} onPress={() => addSteps(2500)}>
          <Text style={styles.btnText}>Walk</Text>
        </TouchableOpacity>
      </View>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, backgroundColor: '#0f172a', padding: 20 },
