```typescript
import fs from 'fs';
import path from 'path';
import matter from 'gray-matter';

const postsDir = path.join(process.cwd(), 'posts');

export interface PostMeta {
  slug: string;
  title: string;
  date: string;
  excerpt: string;
  tags: string[];
}

export interface Post extends PostMeta {
  content: string;
}

export function getAllPosts(): PostMeta[] {
  const files = fs.readdirSync(postsDir).filter(f => f.endsWith('.md'));
  return files
    .map(file => {
      const slug = file.replace('.md', '');
      const raw = fs.readFileSync(path.join(postsDir, file), 'utf-8');
      const { data } = matter(raw);
      return { slug, title: data.title, date: data.date, excerpt: data.excerpt || '', tags: data.tags || [] };
    })
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
}

export function getPostBySlug(slug: string): Post {
  const raw = fs.readFileSync(path.join(postsDir, `${slug}.md`), 'utf-8');
  const { data, content } = matter(raw);
  return { slug, title: data.title, date: data.date, excerpt: data.excerpt || '', tags: data.tags || [], content };
}

export function getAllSlugs(): string[] {
  return fs.readdirSync(postsDir).filter(f => f.endsWith('.md')).map(f => f.replace('.md', ''));
}
