## App.tsx
```tsx
import React, { useState, useEffect, useRef } from 'react';
import { View, Text, TextInput, TouchableOpacity, FlatList, StyleSheet, SafeAreaView, KeyboardAvoidingView, Platform } from 'react-native';

const WS_URL = 'wss://echo.websocket.org'; // Replace with your server

interface Message {
  id: string;
  text: string;
  sender: 'me' | 'other';
  timestamp: number;
}

export default function App() {
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [connected, setConnected] = useState(false);
  const [username] = useState('User_' + Math.random().toString(36).slice(2, 6));
  const ws = useRef<WebSocket | null>(null);
  const flatListRef = useRef<FlatList>(null);

  useEffect(() => {
    ws.current = new WebSocket(WS_URL);
    ws.current.onopen = () => setConnected(true);
    ws.current.onclose = () => setConnected(false);
    ws.current.onmessage = (e) => {
      const msg: Message = { id: Date.now().toString(), text: e.data, sender: 'other', timestamp: Date.now() };
      setMessages(prev => [...prev, msg]);
    };
    return () => ws.current?.close();
  }, []);

  const send = () => {
    if (!input.trim() || !ws.current) return;
    const msg: Message = { id: Date.now().toString(), text: input, sender: 'me', timestamp: Date.now() };
    setMessages(prev => [...prev, msg]);
    ws.current.send(input);
    setInput('');
    setTimeout(() => flatListRef.current?.scrollToEnd(), 100);
  };

  const formatTime = (ts: number) => {
    const d = new Date(ts);
    return d.getHours().toString().padStart(2, '0') + ':' + d.getMinutes().toString().padStart(2, '0');
  };

  return (
    <SafeAreaView style={styles.container}>
      <View style={styles.header}>
        <Text style={styles.headerTitle}>Om Chat</Text>
        <View style={[styles.dot, { backgroundColor: connected ? '#4ade80' : '#ef4444' }]} />
        <Text style={styles.headerSub}>{username}</Text>
      </View>

      <FlatList
        ref={flatListRef}
        data={messages}
        keyExtractor={item => item.id}
        contentContainerStyle={styles.messages}
        onContentSizeChange={() => flatListRef.current?.scrollToEnd()}
        renderItem={({ item }) => (
          <View style={[styles.msgRow, item.sender === 'me' && styles.msgRowMe]}>
            <View style={[styles.bubble, item.sender === 'me' ? styles.bubbleMe : styles.bubbleOther]}>
              <Text style={[styles.msgText, item.sender === 'me' && styles.msgTextMe]}>{item.text}</Text>
              <Text style={styles.msgTime}>{formatTime(item.timestamp)}</Text>
            </View>
          </View>
        )}
      />

      <KeyboardAvoidingView behavior={Platform.OS === 'ios' ? 'padding' : undefined}>
        <View style={styles.inputRow}>
          <TextInput style={styles.input} value={input} onChangeText={setInput} placeholder="Type a message..." placeholderTextColor="#64748b" onSubmitEditing={send} returnKeyType="send" />
          <TouchableOpacity style={styles.sendBtn} onPress={send}>
            <Text style={styles.sendText}>Send</Text>
          </TouchableOpacity>
        </View>
      </KeyboardAvoidingView>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, backgroundColor: '#0f172a' },
  header: { flexDirection: 'row', alignItems: 'center', padding: 16, borderBottomWidth: 1, borderBottomColor: '#1e293b', gap: 8 },
  headerTitle: { fontSize: 18, fontWeight: '700', color: '#fff', flex: 1 },
  headerSub: { fontSize: 12, color: '#64748b' },
  dot: { width: 8, height: 8, borderRadius: 4 },
  messages: { padding: 16, paddingBottom: 8 },
  msgRow: { marginBottom: 8, alignItems: 'flex-start' },
