const express = require('express');
const http = require('http');
const { Server } = require('socket.io');
const path = require('path');

const app = express();
const server = http.createServer(app);
const io = new Server(server, { cors: { origin: '*' } });

app.use(express.static('public'));

let metrics = { users: 142, requests: 8430, errors: 23, responseTime: 45, cpu: 34, memory: 62 };
let history = Array(20).fill(null).map((_, i) => ({ time: Date.now() - (20 - i) * 5000, requests: Math.floor(Math.random() * 100), errors: Math.floor(Math.random() * 5), responseTime: 30 + Math.floor(Math.random() * 40) }));

// Simulate changing metrics
setInterval(() => {
  metrics.users += Math.floor(Math.random() * 10 - 4);
  metrics.requests += Math.floor(Math.random() * 50);
  metrics.errors += Math.random() > 0.8 ? 1 : 0;
  metrics.responseTime = 30 + Math.floor(Math.random() * 40);
  metrics.cpu = Math.min(95, Math.max(10, metrics.cpu + Math.floor(Math.random() * 10 - 5)));
  metrics.memory = Math.min(90, Math.max(30, metrics.memory + Math.floor(Math.random() * 6 - 3)));
  const point = { time: Date.now(), requests: Math.floor(Math.random() * 100), errors: Math.floor(Math.random() * 5), responseTime: metrics.responseTime };
  history.push(point); if (history.length > 60) history.shift();
  io.emit('metrics', metrics);
  io.emit('history_point', point);
}, 2000);

io.on('connection', (socket) => {
  console.log('Client connected');
  socket.emit('metrics', metrics);
  socket.emit('history', history);
  socket.on('disconnect', () => console.log('Client disconnected'));
});

server.listen(3000, () => console.log('Dashboard on http://localhost:3000'));
```

