  document.getElementById('cpu').textContent=d.cpu;
  document.getElementById('memory').textContent=d.memory;
  document.getElementById('cpuBar').style.width=d.cpu+'%';
  document.getElementById('memBar').style.width=d.memory+'%';
});
socket.on('history',d=>{history=d;drawChart()});
socket.on('history_point',d=>{history.push(d);if(history.length>60)history.shift();drawChart()});

function drawChart(){const W=canvas.width,H=canvas.height;ctx.clearRect(0,0,W,H);
  if(!history.length)return;const max=Math.max(...history.map(h=>h.requests),1);
  ctx.beginPath();ctx.strokeStyle='#3b82f6';ctx.lineWidth=2;
  history.forEach((p,i)=>{const x=i/(history.length-1)*W,y=H-((p.requests/max)*H*0.8+H*0.1);
    i===0?ctx.moveTo(x,y):ctx.lineTo(x,y)});ctx.stroke();
  ctx.lineTo(W,H);ctx.lineTo(0,H);ctx.closePath();ctx.fillStyle='rgba(59,130,246,.1)';ctx.fill()}
window.addEventListener('resize',()=>{canvas.width=canvas.offsetWidth;drawChart()});
</script></body></html>
