## App.tsx
```tsx
import React, { useState, useRef } from 'react';
import { View, Text, TextInput, TouchableOpacity, Animated, PanResponder, StyleSheet, SafeAreaView, Dimensions } from 'react-native';
import AsyncStorage from '@react-native-async-storage/async-storage';

const { width } = Dimensions.get('window');
const SWIPE_THRESHOLD = -80;

interface Todo {
  id: string;
  text: string;
  done: boolean;
}

function TodoItem({ item, onToggle, onDelete }: { item: Todo; onToggle: () => void; onDelete: () => void }) {
  const pan = useRef(new Animated.Value(0)).current;
  const opacity = useRef(new Animated.Value(1)).current;
  const height = useRef(new Animated.Value(60)).current;

  const panResponder = PanResponder.create({
    onMoveShouldSetPanResponder: (_, gesture) => Math.abs(gesture.dx) > 10,
    onPanResponderMove: (_, gesture) => {
      if (gesture.dx < 0) pan.setValue(gesture.dx);
    },
    onPanResponderRelease: (_, gesture) => {
      if (gesture.dx < SWIPE_THRESHOLD) {
        Animated.parallel([
          Animated.timing(pan, { toValue: -width, duration: 200, useNativeDriver: false }),
          Animated.timing(opacity, { toValue: 0, duration: 200, useNativeDriver: false }),
          Animated.timing(height, { toValue: 0, duration: 200, useNativeDriver: false }),
        ]).start(onDelete);
      } else {
        Animated.spring(pan, { toValue: 0, useNativeDriver: false }).start();
      }
    },
  });

  return (
    <Animated.View style={[styles.todoWrapper, { opacity, height, transform: [{ translateX: pan }] }]} {...panResponder.panHandlers}>
      <TouchableOpacity style={styles.todo} onPress={onToggle} activeOpacity={0.8}>
        <View style={[styles.checkbox, item.done && styles.checkboxDone]}>
          {item.done && <Text style={styles.check}>✓</Text>}
        </View>
        <Text style={[styles.todoText, item.done && styles.todoDone]}>{item.text}</Text>
      </TouchableOpacity>
      <View style={styles.deleteHint}><Text style={styles.deleteText}>Delete</Text></View>
    </Animated.View>
  );
}

export default function App() {
  const [todos, setTodos] = useState<Todo[]>([]);
  const [input, setInput] = useState('');
  const fadeAnim = useRef(new Animated.Value(0)).current;

  React.useEffect(() => {
    AsyncStorage.getItem('todos').then(d => { if (d) setTodos(JSON.parse(d)); });
    Animated.timing(fadeAnim, { toValue: 1, duration: 600, useNativeDriver: true }).start();
  }, []);

  const save = (updated: Todo[]) => {
    setTodos(updated);
    AsyncStorage.setItem('todos', JSON.stringify(updated));
  };

  const add = () => {
    if (!input.trim()) return;
    save([{ id: Date.now().toString(), text: input.trim(), done: false }, ...todos]);
    setInput('');
  };

  const toggle = (id: string) => save(todos.map(t => t.id === id ? { ...t, done: !t.done } : t));
  const remove = (id: string) => save(todos.filter(t => t.id !== id));

  const pending = todos.filter(t => !t.done).length;

  return (
    <SafeAreaView style={styles.container}>
      <Animated.View style={{ flex: 1, opacity: fadeAnim }}>
        <View style={styles.header}>
          <Text style={styles.title}>Tasks</Text>
          <Text style={styles.count}>{pending} remaining</Text>
        </View>
        <View style={styles.inputRow}>
          <TextInput style={styles.input} value={input} onChangeText={setInput} placeholder="Add a task..." placeholderTextColor="#64748b" onSubmitEditing={add} returnKeyType="done" />
          <TouchableOpacity style={styles.addBtn} onPress={add}>
            <Text style={styles.addText}>+</Text>
          </TouchableOpacity>
        </View>
        <View style={styles.list}>
          {todos.map(item => (
            <TodoItem key={item.id} item={item} onToggle={() => toggle(item.id)} onDelete={() => remove(item.id)} />
          ))}
          {!todos.length && <Text style={styles.empty}>No tasks. Add one above.</Text>}
        </View>
        <Text style={styles.hint}>← Swipe left to delete</Text>
      </Animated.View>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, backgroundColor: '#0f172a', padding: 20 },
  header: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: 20 },
  title: { fontSize: 28, fontWeight: '700', color: '#fff' },
  count: { fontSize: 13, color: '#64748b' },
  inputRow: { flexDirection: 'row', gap: 8, marginBottom: 20 },
  input: { flex: 1, backgroundColor: '#1e293b', borderRadius: 12, paddingHorizontal: 16, paddingVertical: 14, color: '#fff', fontSize: 15, borderWidth: 1, borderColor: '#334155' },
  addBtn: { width: 50, height: 50, backgroundColor: '#4ade80', borderRadius: 12, alignItems: 'center', justifyContent: 'center' },
  addText: { fontSize: 24, color: '#000', fontWeight: '600' },
  list: { flex: 1 },
  todoWrapper: { marginBottom: 8, position: 'relative' },
  todo: { flexDirection: 'row', alignItems: 'center', gap: 12, padding: 14, backgroundColor: '#1e293b', borderRadius: 12, borderWidth: 1, borderColor: '#334155' },
  checkbox: { width: 24, height: 24, borderRadius: 12, borderWidth: 2, borderColor: '#475569', alignItems: 'center', justifyContent: 'center' },
