Here's complete JWT auth — signup, login, protected routes, refresh tokens:

## Backend: server.js
```javascript
const express = require('express');
const mongoose = require('mongoose');
const bcrypt = require('bcryptjs');
const jwt = require('jsonwebtoken');
const cors = require('cors');

const app = express();
app.use(cors());
app.use(express.json());

mongoose.connect(process.env.MONGO_URI || 'mongodb://localhost:27017/auth');

const SECRET = process.env.JWT_SECRET || 'om-secret-key-change-in-prod';
const REFRESH_SECRET = process.env.JWT_REFRESH_SECRET || 'om-refresh-secret';

// User model
const UserSchema = new mongoose.Schema({
  name: { type: String, required: true },
  email: { type: String, required: true, unique: true, lowercase: true },
  password: { type: String, required: true },
  createdAt: { type: Date, default: Date.now }
});
UserSchema.pre('save', async function() { if (this.isModified('password')) this.password = await bcrypt.hash(this.password, 12) });
const User = mongoose.model('User', UserSchema);

// Token model (for refresh tokens)
const TokenSchema = new mongoose.Schema({
  userId: { type: mongoose.Schema.Types.ObjectId, ref: 'User' },
  token: String,
  expiresAt: Date
});
const Token = mongoose.model('Token', TokenSchema);

// Generate tokens
function generateTokens(user) {
  const access = jwt.sign({ id: user._id, email: user.email }, SECRET, { expiresIn: '15m' });
  const refresh = jwt.sign({ id: user._id }, REFRESH_SECRET, { expiresIn: '7d' });
  return { access, refresh };
}

// Auth middleware
function auth(req, res, next) {
  const header = req.headers.authorization;
  if (!header || !header.startsWith('Bearer ')) return res.status(401).json({ error: 'No token provided' });
  try {
    req.user = jwt.verify(header.split(' ')[1], SECRET);
    next();
  } catch (e) {
    if (e.name === 'TokenExpiredError') return res.status(401).json({ error: 'Token expired', code: 'TOKEN_EXPIRED' });
    res.status(401).json({ error: 'Invalid token' });
  }
}

// Routes
app.post('/api/auth/signup', async (req, res) => {
  const { name, email, password } = req.body;
  if (!name || !email || !password) return res.status(400).json({ error: 'All fields required' });
  if (password.length < 6) return res.status(400).json({ error: 'Password must be 6+ chars' });
  const exists = await User.findOne({ email });
  if (exists) return res.status(409).json({ error: 'Email already registered' });
  const user = await User.create({ name, email, password });
  const tokens = generateTokens(user);
  await Token.create({ userId: user._id, token: tokens.refresh, expiresAt: new Date(Date.now() + 7 * 86400000) });
  res.status(201).json({ user: { id: user._id, name: user.name, email: user.email }, ...tokens });
});

app.post('/api/auth/login', async (req, res) => {
  const { email, password } = req.body;
  const user = await User.findOne({ email });
  if (!user || !(await bcrypt.compare(password, user.password)))
    return res.status(401).json({ error: 'Invalid email or password' });
  const tokens = generateTokens(user);
  await Token.create({ userId: user._id, token: tokens.refresh, expiresAt: new Date(Date.now() + 7 * 86400000) });
  res.json({ user: { id: user._id, name: user.name, email: user.email }, ...tokens });
});

app.post('/api/auth/refresh', async (req, res) => {
  const { refreshToken } = req.body;
  if (!refreshToken) return res.status(400).json({ error: 'Refresh token required' });
  const stored = await Token.findOne({ token: refreshToken });
  if (!stored || stored.expiresAt < new Date()) {
    if (stored) await stored.deleteOne();
    return res.status(401).json({ error: 'Invalid refresh token' });
  }
  try {
    const payload = jwt.verify(refreshToken, REFRESH_SECRET);
    const user = await User.findById(payload.id);
    if (!user) return res.status(401).json({ error: 'User not found' });
    await stored.deleteOne();
    const tokens = generateTokens(user);
    await Token.create({ userId: user._id, token: tokens.refresh, expiresAt: new Date(Date.now() + 7 * 86400000) });
    res.json(tokens);
  } catch { res.status(401).json({ error: 'Invalid refresh token' }) }
});

app.post('/api/auth/logout', auth, async (req, res) => {
  await Token.deleteMany({ userId: req.user.id });
  res.json({ message: 'Logged out' });
});

app.get('/api/auth/me', auth, async (req, res) => {
  const user = await User.findById(req.user.id).select('-password');
  res.json(user);
});

// Protected route example
app.get('/api/dashboard', auth, (req, res) => {
  res.json({ message: `Welcome ${req.user.email}! This is protected data.`, timestamp: Date.now() });
});

app.listen(5000, () => console.log('Auth server on :5000'));
```

## Frontend auth hook: useAuth.ts (React)
```typescript
import { useState, useEffect, createContext, useContext } from 'react';

const API = 'http://localhost:5000/api/auth';

interface User { id: string; name: string; email: string }
interface AuthState { user: User | null; loading: boolean }

const AuthContext = createContext<any>(null);

export function AuthProvider({ children }: { children: React.ReactNode }) {
  const [state, setState] = useState<AuthState>({ user: null, loading: true });

  useEffect(() => {
    const token = localStorage.getItem('access_token');
    if (token) fetchUser(token);
    else setState({ user: null, loading: false });
  }, []);

  async function fetchUser(token: string) {
    try {
      const res = await fetch(`${API}/me`, { headers: { Authorization: `Bearer ${token}` } });
      if (res.ok) { setState({ user: await res.json(), loading: false }); return; }
      if (res.status === 401) { await refreshTokens(); return; }
    } catch {}
    setState({ user: null, loading: false });
  }

  async function refreshTokens() {
    const refresh = localStorage.getItem('refresh_token');
    if (!refresh) { logout(); return; }
    const res = await fetch(`${API}/refresh`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ refreshToken: refresh }) });
    if (res.ok) {
      const { access, refresh: newRefresh } = await res.json();
      localStorage.setItem('access_token', access);
      localStorage.setItem('refresh_token', newRefresh);
      await fetchUser(access);
    } else logout();
  }

  async function login(email: string, password: string) {
    const res = await fetch(`${API}/login`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ email, password }) });
    if (!res.ok) throw new Error((await res.json()).error);
    const data = await res.json();
    localStorage.setItem('access_token', data.access);
    localStorage.setItem('refresh_token', data.refresh);
    setState({ user: data.user, loading: false });
  }

  async function signup(name: string, email: string, password: string) {
    const res = await fetch(`${API}/signup`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name, email, password }) });
    if (!res.ok) throw new Error((await res.json()).error);
    const data = await res.json();
    localStorage.setItem('access_token', data.access);
    localStorage.setItem('refresh_token', data.refresh);
    setState({ user: data.user, loading: false });
  }

  function logout() {
    localStorage.removeItem('access_token');
    localStorage.removeItem('refresh_token');
    setState({ user: null, loading: false });
  }

  return <AuthContext.Provider value={{ ...state, login, signup, logout }}>{children}</AuthContext.Provider>;
}

export const useAuth = () => useContext(AuthContext);
