Here's a complete GraphQL social media API with users, posts, likes, and comments:

## server.js
```javascript
const { ApolloServer } = require('@apollo/server');
const { startStandaloneServer } = require('@apollo/server/standalone');
const { GraphQLError } = require('graphql');
const jwt = require('jsonwebtoken');
const bcrypt = require('bcryptjs');

const SECRET = 'om-graphql-secret';

// In-memory store (replace with MongoDB in production)
let users = [
  { id: '1', username: 'om', email: 'om@example.com', password: '$2a$12$LQv3c1yqBo9SkvXS7QTJPOoFHv7LGz5rGMvq60mS/kr0gN1cZ1Kfe', bio: 'The Divine Architect', avatar: null, createdAt: new Date().toISOString() }
];
let posts = [];
let comments = [];
let likes = [];
let nextId = 100;

const typeDefs = `#graphql
  type User {
    id: ID!
    username: String!
    email: String!
    bio: String
    avatar: String
    posts: [Post!]!
    createdAt: String!
  }

  type Post {
    id: ID!
    content: String!
    author: User!
    comments: [Comment!]!
    likes: [Like!]!
    likeCount: Int!
    commentCount: Int!
    createdAt: String!
  }

  type Comment {
    id: ID!
    content: String!
    author: User!
    post: Post!
    createdAt: String!
  }

  type Like {
    id: ID!
    user: User!
    post: Post!
  }

  type AuthPayload {
    token: String!
    user: User!
  }

  type Query {
    me: User
    user(id: ID!): User
    users: [User!]!
    posts(limit: Int, offset: Int): [Post!]!
    post(id: ID!): Post
    feed: [Post!]!
  }

  type Mutation {
    signup(username: String!, email: String!, password: String!): AuthPayload!
    login(email: String!, password: String!): AuthPayload!
    createPost(content: String!): Post!
    deletePost(id: ID!): Boolean!
    likePost(postId: ID!): Post!
    unlikePost(postId: ID!): Post!
    addComment(postId: ID!, content: String!): Comment!
    deleteComment(id: ID!): Boolean!
    updateProfile(bio: String, avatar: String): User!
  }
`;

function getUser(context) {
  if (!context.user) throw new GraphQLError('Authentication required', { extensions: { code: 'UNAUTHENTICATED' } });
  return context.user;
}

const resolvers = {
  Query: {
    me: (_, __, ctx) => { const u = getUser(ctx); return users.find(x => x.id === u.id); },
    user: (_, { id }) => users.find(u => u.id === id),
    users: () => users,
    posts: (_, { limit = 20, offset = 0 }) => posts.slice(offset, offset + limit).sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt)),
    post: (_, { id }) => posts.find(p => p.id === id),
    feed: () => posts.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt)).slice(0, 50),
  },
  Mutation: {
    signup: async (_, { username, email, password }) => {
      if (users.find(u => u.email === email)) throw new GraphQLError('Email taken');
      const id = String(++nextId);
      const hashed = await bcrypt.hash(password, 12);
      const user = { id, username, email, password: hashed, bio: '', avatar: null, createdAt: new Date().toISOString() };
      users.push(user);
      const token = jwt.sign({ id, email }, SECRET, { expiresIn: '7d' });
      return { token, user };
    },
    login: async (_, { email, password }) => {
      const user = users.find(u => u.email === email);
      if (!user || !(await bcrypt.compare(password, user.password))) throw new GraphQLError('Invalid credentials');
      const token = jwt.sign({ id: user.id, email }, SECRET, { expiresIn: '7d' });
      return { token, user };
    },
    createPost: (_, { content }, ctx) => {
      const u = getUser(ctx);
      const post = { id: String(++nextId), content, authorId: u.id, createdAt: new Date().toISOString() };
      posts.push(post); return post;
    },
    deletePost: (_, { id }, ctx) => {
      const u = getUser(ctx);
      const idx = posts.findIndex(p => p.id === id && p.authorId === u.id);
      if (idx < 0) throw new GraphQLError('Not found or not authorized');
      posts.splice(idx, 1); comments = comments.filter(c => c.postId !== id); likes = likes.filter(l => l.postId !== id);
      return true;
    },
    likePost: (_, { postId }, ctx) => {
      const u = getUser(ctx);
      if (likes.find(l => l.postId === postId && l.userId === u.id)) throw new GraphQLError('Already liked');
      likes.push({ id: String(++nextId), postId, userId: u.id });
      return posts.find(p => p.id === postId);
    },
    unlikePost: (_, { postId }, ctx) => {
      const u = getUser(ctx);
      likes = likes.filter(l => !(l.postId === postId && l.userId === u.id));
      return posts.find(p => p.id === postId);
    },
    addComment: (_, { postId, content }, ctx) => {
      const u = getUser(ctx);
      const comment = { id: String(++nextId), postId, content, authorId: u.id, createdAt: new Date().toISOString() };
      comments.push(comment); return comment;
    },
    deleteComment: (_, { id }, ctx) => {
      const u = getUser(ctx);
      const idx = comments.findIndex(c => c.id === id && c.authorId === u.id);
      if (idx < 0) return false;
      comments.splice(idx, 1); return true;
    },
    updateProfile: (_, { bio, avatar }, ctx) => {
      const u = getUser(ctx);
      const user = users.find(x => x.id === u.id);
      if (bio !== undefined) user.bio = bio;
      if (avatar !== undefined) user.avatar = avatar;
      return user;
    },
  },
  User: { posts: (user) => posts.filter(p => p.authorId === user.id) },
  Post: {
    author: (post) => users.find(u => u.id === post.authorId),
    comments: (post) => comments.filter(c => c.postId === post.id),
    likes: (post) => likes.filter(l => l.postId === post.id),
    likeCount: (post) => likes.filter(l => l.postId === post.id).length,
    commentCount: (post) => comments.filter(c => c.postId === post.id).length,
  },
  Comment: {
    author: (c) => users.find(u => u.id === c.authorId),
    post: (c) => posts.find(p => p.id === c.postId),
  },
  Like: {
    user: (l) => users.find(u => u.id === l.userId),
    post: (l) => posts.find(p => p.id === l.postId),
  },
};

async function start() {
  const server = new ApolloServer({ typeDefs, resolvers });
  const { url } = await startStandaloneServer(server, {
    listen: { port: 4000 },
    context: async ({ req }) => {
      const token = req.headers.authorization?.replace('Bearer ', '');
      if (token) {
        try { return { user: jwt.verify(token, SECRET) }; } catch {}
      }
      return { user: null };
    },
  });
  console.log(`GraphQL API at ${url}`);
}
start();
```

