## App.vue
```vue
<template>
  <div id="app">
    <header>
      <h1>Portfolio Tracker</h1>
      <div class="total">
        <span class="label">Total Value</span>
        <span class="value">${{ totalValue.toFixed(2) }}</span>
        <span :class="['change', totalPnL >= 0 ? 'up' : 'down']">
          {{ totalPnL >= 0 ? '+' : '' }}{{ totalPnL.toFixed(2) }} ({{ totalPnLPct.toFixed(1) }}%)
        </span>
      </div>
    </header>

    <div class="add-form">
      <input v-model="newSymbol" placeholder="Symbol (e.g. AAPL)" @keyup.enter="addStock" />
      <input v-model.number="newShares" type="number" placeholder="Shares" />
      <input v-model.number="newCost" type="number" placeholder="Cost/share" />
      <button @click="addStock">Add</button>
    </div>

    <div class="holdings">
      <div class="holding" v-for="h in holdings" :key="h.symbol">
        <div class="symbol">{{ h.symbol }}</div>
        <div class="details">
          <div class="price">${{ h.currentPrice.toFixed(2) }}</div>
          <div class="shares">{{ h.shares }} shares @ ${{ h.costBasis.toFixed(2) }}</div>
        </div>
        <div class="pnl-col">
          <div :class="['pnl', h.pnl >= 0 ? 'up' : 'down']">
            {{ h.pnl >= 0 ? '+' : '' }}${{ h.pnl.toFixed(2) }}
          </div>
          <div :class="['pnl-pct', h.pnlPct >= 0 ? 'up' : 'down']">
            {{ h.pnlPct >= 0 ? '+' : '' }}{{ h.pnlPct.toFixed(1) }}%
          </div>
        </div>
        <button class="del" @click="removeStock(h.symbol)">×</button>
      </div>
    </div>

    <div class="chart">
      <h3>Allocation</h3>
      <div class="bars">
        <div v-for="h in holdings" :key="h.symbol" class="bar"
          :style="{ width: (h.currentPrice * h.shares / totalValue * 100) + '%', background: h.color }">
          <span v-if="(h.currentPrice * h.shares / totalValue) > 0.1">{{ h.symbol }}</span>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import { ref, computed, onMounted, onUnmounted } from 'vue';

export default {
  setup() {
    const holdings = ref(JSON.parse(localStorage.getItem('portfolio') || '[]'));
    const newSymbol = ref(''); const newShares = ref(null); const newCost = ref(null);
    const colors = ['#3b82f6','#4ade80','#f97316','#a78bfa','#f472b6','#fbbf24','#06b6d4','#ef4444'];
    let interval = null;

    function save() { localStorage.setItem('portfolio', JSON.stringify(holdings.value)); }

    function addStock() {
      if (!newSymbol.value || !newShares.value || !newCost.value) return;
      holdings.value.push({
        symbol: newSymbol.value.toUpperCase(), shares: newShares.value,
        costBasis: newCost.value, currentPrice: newCost.value,
        color: colors[holdings.value.length % colors.length]
      });
      newSymbol.value = ''; newShares.value = null; newCost.value = null; save();
    }

    function removeStock(symbol) { holdings.value = holdings.value.filter(h => h.symbol !== symbol); save(); }

    function simulatePrices() {
      holdings.value.forEach(h => {
        const change = (Math.random() - 0.48) * h.currentPrice * 0.02;
        h.currentPrice = Math.max(0.01, h.currentPrice + change);
      });
    }

    const totalValue = computed(() => holdings.value.reduce((s, h) => s + h.currentPrice * h.shares, 0));
    const totalCost = computed(() => holdings.value.reduce((s, h) => s + h.costBasis * h.shares, 0));
    const totalPnL = computed(() => totalValue.value - totalCost.value);
    const totalPnLPct = computed(() => totalCost.value ? (totalPnL.value / totalCost.value) * 100 : 0);

    const enrichedHoldings = computed(() => holdings.value.map(h => ({
      ...h,
      pnl: (h.currentPrice - h.costBasis) * h.shares,
      pnlPct: ((h.currentPrice - h.costBasis) / h.costBasis) * 100
    })));

    onMounted(() => { interval = setInterval(simulatePrices, 2000); });
    onUnmounted(() => clearInterval(interval));

    return { holdings: enrichedHoldings, newSymbol, newShares, newCost, addStock, removeStock, totalValue, totalPnL, totalPnLPct };
  }
};
</script>

