```svelte
<script>
  import { onMount } from 'svelte';

  let canvas, ctx;
  let drawing = false;
  let tool = 'pen'; // pen, eraser, rect, circle
  let color = '#60a5fa';
  let lineWidth = 3;
  let startX, startY;
  let history = [];
  let historyIndex = -1;

  onMount(() => {
    ctx = canvas.getContext('2d');
    resize();
    window.addEventListener('resize', resize);
    saveState();
  });

  function resize() {
    const data = ctx.getImageData(0, 0, canvas.width, canvas.height);
    canvas.width = canvas.parentElement.offsetWidth;
    canvas.height = window.innerHeight - 120;
    ctx.putImageData(data, 0, 0);
    ctx.lineCap = 'round'; ctx.lineJoin = 'round';
  }

  function getPos(e) {
    const rect = canvas.getBoundingClientRect();
    const touch = e.touches ? e.touches[0] : e;
    return { x: touch.clientX - rect.left, y: touch.clientY - rect.top };
  }

  function startDraw(e) {
    drawing = true;
    const pos = getPos(e);
    startX = pos.x; startY = pos.y;
    if (tool === 'pen' || tool === 'eraser') {
      ctx.beginPath();
      ctx.moveTo(pos.x, pos.y);
    }
  }

  function draw(e) {
    if (!drawing) return;
    const pos = getPos(e);
    if (tool === 'pen') {
      ctx.strokeStyle = color;
      ctx.lineWidth = lineWidth;
      ctx.lineTo(pos.x, pos.y);
      ctx.stroke();
    } else if (tool === 'eraser') {
      ctx.strokeStyle = '#1e293b';
      ctx.lineWidth = 20;
      ctx.lineTo(pos.x, pos.y);
      ctx.stroke();
    }
  }

  function endDraw(e) {
    if (!drawing) return;
    drawing = false;
    const pos = getPos(e.changedTouches ? e.changedTouches[0] : e);

    if (tool === 'rect') {
      ctx.strokeStyle = color; ctx.lineWidth = lineWidth;
      ctx.strokeRect(startX, startY, pos.x - startX, pos.y - startY);
    } else if (tool === 'circle') {
      ctx.strokeStyle = color; ctx.lineWidth = lineWidth;
      const rx = Math.abs(pos.x - startX) / 2, ry = Math.abs(pos.y - startY) / 2;
      const cx = startX + (pos.x - startX) / 2, cy = startY + (pos.y - startY) / 2;
      ctx.beginPath(); ctx.ellipse(cx, cy, rx, ry, 0, 0, Math.PI * 2); ctx.stroke();
    }
    saveState();
  }

  function saveState() {
    historyIndex++;
    history = history.slice(0, historyIndex);
    history.push(canvas.toDataURL());
  }

  function undo() {
    if (historyIndex <= 0) return;
    historyIndex--;
    const img = new Image();
    img.onload = () => { ctx.clearRect(0, 0, canvas.width, canvas.height); ctx.drawImage(img, 0, 0); };
    img.src = history[historyIndex];
  }

  function redo() {
    if (historyIndex >= history.length - 1) return;
    historyIndex++;
    const img = new Image();
    img.onload = () => { ctx.clearRect(0, 0, canvas.width, canvas.height); ctx.drawImage(img, 0, 0); };
    img.src = history[historyIndex];
  }

  function clearCanvas() {
    ctx.fillStyle = '#1e293b';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    saveState();
  }

  function download() {
    const a = document.createElement('a');
    a.download = 'whiteboard.png';
    a.href = canvas.toDataURL();
    a.click();
  }

  const colors = ['#ef4444','#f97316','#fbbf24','#4ade80','#60a5fa','#a78bfa','#f472b6','#fff'];
</script>

