Here's a Flask ML prediction API with model loading, validation, and batch prediction:

## app.py
```python
from flask import Flask, request, jsonify
from flask_cors import CORS
import numpy as np
import joblib
import os
from datetime import datetime
from functools import wraps
import logging

app = Flask(__name__)
CORS(app)
logging.basicConfig(level=logging.INFO)

# Model registry
models = {}
model_metadata = {}

def load_models():
    """Load all models from the models/ directory."""
    model_dir = os.path.join(os.path.dirname(__file__), 'models')
    os.makedirs(model_dir, exist_ok=True)
    for filename in os.listdir(model_dir):
        if filename.endswith('.joblib'):
            name = filename.replace('.joblib', '')
            models[name] = joblib.load(os.path.join(model_dir, filename))
            model_metadata[name] = {
                'loaded_at': datetime.now().isoformat(),
                'file': filename,
                'size_mb': os.path.getsize(os.path.join(model_dir, filename)) / 1024 / 1024
            }
            logging.info(f'Loaded model: {name}')

# Create a dummy model for demo
def create_demo_model():
    from sklearn.ensemble import RandomForestClassifier
    from sklearn.datasets import make_classification
    X, y = make_classification(n_samples=1000, n_features=10, random_state=42)
    model = RandomForestClassifier(n_estimators=100, random_state=42)
    model.fit(X, y)
    os.makedirs('models', exist_ok=True)
    joblib.dump(model, 'models/demo_classifier.joblib')
    logging.info('Created demo model')

def require_json(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        if not request.is_json:
            return jsonify({'error': 'Content-Type must be application/json'}), 400
        return f(*args, **kwargs)
    return decorated

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'models_loaded': len(models), 'timestamp': datetime.now().isoformat()})

@app.route('/models', methods=['GET'])
def list_models():
    return jsonify({'models': [
        {'name': name, **meta} for name, meta in model_metadata.items()
    ]})

@app.route('/predict/<model_name>', methods=['POST'])
@require_json
def predict(model_name):
    if model_name not in models:
        return jsonify({'error': f'Model "{model_name}" not found', 'available': list(models.keys())}), 404

    data = request.json
    features = data.get('features')
    if features is None:
        return jsonify({'error': 'Missing "features" field'}), 400

    try:
        X = np.array(features)
        if X.ndim == 1:
            X = X.reshape(1, -1)

        model = models[model_name]
        predictions = model.predict(X).tolist()

        response = {'model': model_name, 'predictions': predictions, 'count': len(predictions)}

        # Add probabilities if available
        if hasattr(model, 'predict_proba'):
            probas = model.predict_proba(X).tolist()
            response['probabilities'] = probas

        return jsonify(response)

    except ValueError as e:
        return jsonify({'error': f'Invalid features: {str(e)}'}), 400
    except Exception as e:
        logging.exception('Prediction error')
        return jsonify({'error': f'Prediction failed: {str(e)}'}), 500

@app.route('/predict/<model_name>/batch', methods=['POST'])
@require_json
def predict_batch(model_name):
    if model_name not in models:
        return jsonify({'error': f'Model "{model_name}" not found'}), 404

    data = request.json
    batch = data.get('batch', [])
    if not batch:
        return jsonify({'error': 'Empty batch'}), 400
    if len(batch) > 1000:
        return jsonify({'error': 'Batch size exceeds limit (1000)'}), 400

    try:
        X = np.array(batch)
        model = models[model_name]
        predictions = model.predict(X).tolist()
        return jsonify({'model': model_name, 'predictions': predictions, 'count': len(predictions)})
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/model/<model_name>/upload', methods=['POST'])
def upload_model(model_name):
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400
    file = request.files['file']
    path = os.path.join('models', f'{model_name}.joblib')
    file.save(path)
    models[model_name] = joblib.load(path)
    model_metadata[model_name] = {'loaded_at': datetime.now().isoformat(), 'file': f'{model_name}.joblib',
        'size_mb': os.path.getsize(path) / 1024 / 1024}
    return jsonify({'message': f'Model "{model_name}" uploaded and loaded', 'metadata': model_metadata[model_name]}), 201

@app.errorhandler(404)
def not_found(e):
    return jsonify({'error': 'Endpoint not found'}), 404

@app.errorhandler(500)
def server_error(e):
    return jsonify({'error': 'Internal server error'}), 500

if __name__ == '__main__':
    if not os.listdir('models') if os.path.exists('models') else True:
        create_demo_model()
    load_models()
    app.run(host='0.0.0.0', port=5000, debug=True)
```

