## views.py
```python
from rest_framework import viewsets, permissions, status
from rest_framework.decorators import action
from rest_framework.response import Response
from django.utils import timezone
from .models import Course, Lesson, Enrollment, LessonProgress
from .serializers import CourseListSerializer, CourseDetailSerializer, LessonSerializer, EnrollmentSerializer

class IsInstructorOrReadOnly(permissions.BasePermission):
    def has_object_permission(self, request, view, obj):
        if request.method in permissions.SAFE_METHODS:
            return True
        return obj.instructor == request.user

class CourseViewSet(viewsets.ModelViewSet):
    permission_classes = [permissions.IsAuthenticatedOrReadOnly, IsInstructorOrReadOnly]

    def get_queryset(self):
        qs = Course.objects.all()
        if self.action == 'list':
            qs = qs.filter(is_published=True)
        return qs

    def get_serializer_class(self):
        if self.action == 'retrieve':
            return CourseDetailSerializer
        return CourseListSerializer

    def perform_create(self, serializer):
        serializer.save(instructor=self.request.user)

    @action(detail=True, methods=['post'], permission_classes=[permissions.IsAuthenticated])
    def enroll(self, request, pk=None):
        course = self.get_object()
        enrollment, created = Enrollment.objects.get_or_create(student=request.user, course=course)
        if not created:
            return Response({'detail': 'Already enrolled'}, status=status.HTTP_400_BAD_REQUEST)
        return Response(EnrollmentSerializer(enrollment).data, status=status.HTTP_201_CREATED)

    @action(detail=True, methods=['post'], url_path='lessons/(?P<lesson_id>[^/.]+)/complete',
            permission_classes=[permissions.IsAuthenticated])
    def complete_lesson(self, request, pk=None, lesson_id=None):
        course = self.get_object()
        try:
            enrollment = Enrollment.objects.get(student=request.user, course=course)
            lesson = course.lessons.get(id=lesson_id)
        except (Enrollment.DoesNotExist, Lesson.DoesNotExist) as e:
            return Response({'detail': str(e)}, status=status.HTTP_404_NOT_FOUND)

        LessonProgress.objects.get_or_create(enrollment=enrollment, lesson=lesson)

        # Check if course is complete
        if enrollment.progress == 100:
            enrollment.completed_at = timezone.now()
            enrollment.save()

        return Response({'progress': enrollment.progress, 'completed': enrollment.completed_at is not None})

class EnrollmentViewSet(viewsets.ReadOnlyModelViewSet):
    serializer_class = EnrollmentSerializer
    permission_classes = [permissions.IsAuthenticated]

    def get_queryset(self):
        return Enrollment.objects.filter(student=self.request.user)
