Here's a sentiment analysis API using transformers and FastAPI with caching:

## main.py
```python
from fastapi import FastAPI, HTTPException
from fastapi.middleware.cors import CORSMiddleware
from pydantic import BaseModel
from transformers import pipeline
from functools import lru_cache
import hashlib
import time
from typing import Optional

app = FastAPI(title='Om Sentiment API', version='1.0.0')
app.add_middleware(CORSMiddleware, allow_origins=['*'], allow_methods=['*'], allow_headers=['*'])

# Load model once
@lru_cache(maxsize=1)
def get_model():
    return pipeline('sentiment-analysis', model='distilbert-base-uncased-finetuned-sst-2-english', device=-1)

class TextInput(BaseModel):
    text: str
    threshold: Optional[float] = 0.5

class BatchInput(BaseModel):
    texts: list[str]

class SentimentResult(BaseModel):
    text: str
    sentiment: str
    confidence: float
    processing_time_ms: float

# Result cache
cache: dict = {}

def get_cache_key(text: str) -> str:
    return hashlib.md5(text.encode()).hexdigest()

@app.get('/health')
def health():
    return {'status': 'ok', 'model': 'distilbert-sst2'}

@app.post('/analyze', response_model=SentimentResult)
def analyze(input: TextInput):
    if not input.text.strip():
        raise HTTPException(400, 'Text cannot be empty')
    if len(input.text) > 5000:
        raise HTTPException(400, 'Text too long (max 5000 chars)')

    key = get_cache_key(input.text)
    if key in cache:
        return cache[key]

    start = time.time()
    model = get_model()
    result = model(input.text[:512])[0]  # truncate for model max length
    elapsed = (time.time() - start) * 1000

    output = SentimentResult(
        text=input.text[:100] + ('...' if len(input.text) > 100 else ''),
        sentiment=result['label'].lower(),
        confidence=round(result['score'], 4),
        processing_time_ms=round(elapsed, 2)
    )
    cache[key] = output
    return output

@app.post('/analyze/batch')
def analyze_batch(input: BatchInput):
    if len(input.texts) > 50:
        raise HTTPException(400, 'Max 50 texts per batch')

    model = get_model()
    start = time.time()
    results = model(input.texts)
    elapsed = (time.time() - start) * 1000

    return {
        'results': [{
            'text': t[:100],
            'sentiment': r['label'].lower(),
            'confidence': round(r['score'], 4)
        } for t, r in zip(input.texts, results)],
        'count': len(input.texts),
        'total_time_ms': round(elapsed, 2)
    }

@app.post('/analyze/detailed')
def analyze_detailed(input: TextInput):
    """Returns sentence-level breakdown."""
    import re
    sentences = [s.strip() for s in re.split(r'[.!?]+', input.text) if s.strip()]
    if not sentences:
        raise HTTPException(400, 'No sentences found')

    model = get_model()
    results = model(sentences)

    positive = sum(1 for r in results if r['label'] == 'POSITIVE')
    negative = len(results) - positive
    overall = 'positive' if positive > negative else 'negative' if negative > positive else 'mixed'

    return {
        'overall_sentiment': overall,
        'positive_sentences': positive,
        'negative_sentences': negative,
        'sentences': [{
            'text': s, 'sentiment': r['label'].lower(), 'confidence': round(r['score'], 4)
        } for s, r in zip(sentences, results)]
    }

if __name__ == '__main__':
    import uvicorn
    get_model()  # warm up
    uvicorn.run(app, host='0.0.0.0', port=8000)
```

