  maze=Array(GRID).fill(null).map(()=>Array(GRID).fill(1));
  function carve(x,y){maze[y][x]=0;const dirs=[[0,-2],[0,2],[-2,0],[2,0]].sort(()=>Math.random()-.5);
    for(const[dx,dy]of dirs){const nx=x+dx,ny=y+dy;
      if(nx>0&&nx<GRID-1&&ny>0&&ny<GRID-1&&maze[ny][nx]===1){maze[y+dy/2][x+dx/2]=0;carve(nx,ny)}}}
  carve(1,1);
}
generateMaze();

// Build 3D walls
const wallMat=new THREE.MeshLambertMaterial({color:0x4a3728});
const floorMat=new THREE.MeshLambertMaterial({color:0x2a1f1a});
const ceilMat=new THREE.MeshLambertMaterial({color:0x1a1210});

function buildLevel(){
  // Clear old
  while(scene.children.length>0)scene.remove(scene.children[0]);
  // Floor + ceiling
  const floorGeo=new THREE.PlaneGeometry(GRID*CELL,GRID*CELL);
  const floor=new THREE.Mesh(floorGeo,floorMat);floor.rotation.x=-Math.PI/2;floor.position.set(GRID*CELL/2,0,GRID*CELL/2);scene.add(floor);
  const ceil=new THREE.Mesh(floorGeo,ceilMat);ceil.rotation.x=Math.PI/2;ceil.position.set(GRID*CELL/2,CELL,GRID*CELL/2);scene.add(ceil);
  // Walls
  const wallGeo=new THREE.BoxGeometry(CELL,CELL,CELL);
  for(let y=0;y<GRID;y++)for(let x=0;x<GRID;x++){if(maze[y][x]===1){
    const w=new THREE.Mesh(wallGeo,wallMat);w.position.set(x*CELL+CELL/2,CELL/2,y*CELL+CELL/2);w.castShadow=true;scene.add(w)}}
  // Lights
  const ambient=new THREE.AmbientLight(0x111111);scene.add(ambient);
  const torch=new THREE.PointLight(0xff8844,1.5,8);torch.position.copy(camera.position);scene.add(torch);
  return torch;
}

let torch=buildLevel();
camera.position.set(1*CELL+CELL/2,CELL*0.6,1*CELL+CELL/2);

// Player state
let health=100,kills=0,keys=0,floor_num=1;
let vx=0,vz=0,vy=0;
const speed=0.06,rotSpeed=0.003;
let yaw=0,pitch=0;

// Pointer lock
renderer.domElement.addEventListener('click',()=>renderer.domElement.requestPointerLock());
document.addEventListener('mousemove',e=>{if(document.pointerLockElement){
  yaw-=e.movementX*rotSpeed;pitch-=e.movementY*rotSpeed;pitch=Math.max(-1.2,Math.min(1.2,pitch))}});

// Keys
const pressed={};
document.addEventListener('keydown',e=>pressed[e.code]=true);
document.addEventListener('keyup',e=>pressed[e.code]=false);

// Enemies
let enemies=[];
function spawnEnemies(count){
  enemies=[];
  const enemyGeo=new THREE.SphereGeometry(0.3,8,8);
  const enemyMat=new THREE.MeshLambertMaterial({color:0xff0000,emissive:0x330000});
  for(let i=0;i<count;i++){let ex,ey;do{ex=Math.floor(Math.random()*(GRID-2))+1;ey=Math.floor(Math.random()*(GRID-2))+1}while(maze[ey][ex]===1||(ex===1&&ey===1));
    const mesh=new THREE.Mesh(enemyGeo,enemyMat);mesh.position.set(ex*CELL+CELL/2,0.5,ey*CELL+CELL/2);mesh.castShadow=true;scene.add(mesh);
    enemies.push({mesh,hp:30,speed:0.015+Math.random()*0.01})}}
spawnEnemies(5);

// Combat
document.addEventListener('click',()=>{if(!document.pointerLockElement)return;
  const ray=new THREE.Raycaster();ray.setFromCamera(new THREE.Vector2(0,0),camera);ray.far=6;
  const hits=ray.intersectObjects(enemies.map(e=>e.mesh));
  if(hits.length){const e=enemies.find(en=>en.mesh===hits[0].object);
    if(e){e.hp-=25;if(e.hp<=0){scene.remove(e.mesh);enemies=enemies.filter(en=>en!==e);kills++;document.getElementById('kills').textContent=kills;
      if(!enemies.length)showMsg('Floor cleared! Find the exit...')}}}});

// Collision
function canMove(x,z){const gx=Math.floor(x/CELL),gz=Math.floor(z/CELL);if(gx<0||gx>=GRID||gz<0||gz>=GRID)return false;return maze[gz][gx]===0}

function showMsg(t){const el=document.getElementById('msg');el.textContent=t;el.style.opacity='1';setTimeout(()=>el.style.opacity='0',2000)}

// Minimap
const miniCtx=document.getElementById('minimap').getContext('2d');
function drawMinimap(){miniCtx.fillStyle='#000';miniCtx.fillRect(0,0,120,120);
  const s=120/GRID;
  for(let y=0;y<GRID;y++)for(let x=0;x<GRID;x++){miniCtx.fillStyle=maze[y][x]?'#333':'#1a1a2e';miniCtx.fillRect(x*s,y*s,s-1,s-1)}
  const px=camera.position.x/CELL*s,pz=camera.position.z/CELL*s;
  miniCtx.fillStyle='#4ade80';miniCtx.beginPath();miniCtx.arc(px,pz,3,0,Math.PI*2);miniCtx.fill();
  enemies.forEach(e=>{miniCtx.fillStyle='#ef4444';miniCtx.beginPath();miniCtx.arc(e.mesh.position.x/CELL*s,e.mesh.position.z/CELL*s,2,0,Math.PI*2);miniCtx.fill()})}

// Game loop
function update(){
  // Movement
  let moveX=0,moveZ=0;
  if(pressed['KeyW'])moveZ=-1;if(pressed['KeyS'])moveZ=1;
  if(pressed['KeyA'])moveX=-1;if(pressed['KeyD'])moveX=1;
  const forward=new THREE.Vector3(-Math.sin(yaw)*moveZ-Math.sin(yaw+Math.PI/2)*moveX,0,-Math.cos(yaw)*moveZ-Math.cos(yaw+Math.PI/2)*moveX);
  if(forward.length()>0)forward.normalize().multiplyScalar(speed);
  const nx=camera.position.x+forward.x,nz=camera.position.z+forward.z;
  if(canMove(nx,camera.position.z))camera.position.x=nx;
  if(canMove(camera.position.x,nz))camera.position.z=nz;
  camera.rotation.set(pitch,yaw,0,'YXZ');
  torch.position.copy(camera.position);

  // Enemy AI
  enemies.forEach(e=>{const dir=new THREE.Vector3().subVectors(camera.position,e.mesh.position).normalize();
    e.mesh.position.add(dir.multiplyScalar(e.speed));
    if(e.mesh.position.distanceTo(camera.position)<0.6){health-=0.3;document.getElementById('health-fill').style.width=Math.max(0,health)+'%';
      if(health<=0)showMsg('You died! Refresh to restart.')}});

  // Head bob
  camera.position.y=CELL*0.6+Math.sin(Date.now()*0.005)*0.02;
  drawMinimap();
  renderer.render(scene,camera);requestAnimationFrame(update)}
update();
window.addEventListener('resize',()=>{camera.aspect=window.innerWidth/window.innerHeight;camera.updateProjectionMatrix();renderer.setSize(window.innerWidth,window.innerHeight)});
</script></body></html>
