    <div class="input-row">
      <textarea id="input" rows="1" placeholder="Message Om..." onkeydown="if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();send()}" oninput="autoResize(this)"></textarea>
      <button class="send-btn" id="sendBtn" onclick="send()">&#9654;</button>
    </div>
  </div>
