<script>
let conversations=JSON.parse(localStorage.getItem('om_convs')||'[]');
let activeId=null,streaming=false;

function newConversation(){const id=Date.now().toString();conversations.unshift({id,title:'New Chat',messages:[]});activeId=id;save();render()}
function save(){localStorage.setItem('om_convs',JSON.stringify(conversations))}
function getActive(){return conversations.find(c=>c.id===activeId)}

function render(){
  document.getElementById('convList').innerHTML=conversations.map(c=>
    `<div class="conv-item${c.id===activeId?' active':''}" onclick="loadConv('${c.id}')">${c.title}</div>`).join('');
  renderMessages();
}

function loadConv(id){activeId=id;render()}

function renderMessages(){
  const conv=getActive();const el=document.getElementById('messages');
  if(!conv||!conv.messages.length){el.innerHTML='<div class="empty"><h2>Om Chat</h2><p>How can I help you today?</p></div>';return}
  el.innerHTML=conv.messages.map(m=>`<div class="msg ${m.role}">
    <div class="avatar ${m.role==='user'?'user-av':'ai-av'}">${m.role==='user'?'U':'Om'}</div>
    <div class="msg-content">${escapeHtml(m.content)}</div></div>`).join('');
  el.scrollTop=el.scrollHeight;
}

function escapeHtml(t){return t.replace(/</g,'&lt;').replace(/>/g,'&gt;')}
function autoResize(el){el.style.height='auto';el.style.height=Math.min(el.scrollHeight,200)+'px'}

async function send(){
  const input=document.getElementById('input');const text=input.value.trim();
  if(!text||streaming)return;
  if(!activeId)newConversation();
  const conv=getActive();
  conv.messages.push({role:'user',content:text});
  if(conv.title==='New Chat')conv.title=text.slice(0,30);
  input.value='';autoResize(input);save();renderMessages();

  // Simulate streaming response
  streaming=true;
  conv.messages.push({role:'assistant',content:''});
  const responses=['I understand you want to '+text.toLowerCase()+'. Let me help with that.\n\nHere is my analysis:\n\n','1. First, we need to consider the architecture...\n','2. Then implement the core logic...\n','3. Finally, add error handling and tests.\n\n','Would you like me to write the code for this?'];
  for(const chunk of responses){
    for(const char of chunk){conv.messages[conv.messages.length-1].content+=char;renderMessages();await new Promise(r=>setTimeout(r,20))}
  }
  streaming=false;save();
}

if(!conversations.length)newConversation();else{activeId=conversations[0].id}render();
</script></body></html>
