<div class="app">
<h1>Om Health</h1>
<p class="subtitle">AI-Powered Symptom Checker</p>
<div class="disclaimer">&#9888; This tool provides general health information only. It is NOT a substitute for professional medical advice, diagnosis, or treatment. Always consult a qualified healthcare provider.</div>

<div class="step active" id="step1">
  <div class="step-header">Step 1: Where is the problem?</div>
  <div class="body-map" id="bodyRegions"></div>
  <div class="nav-btns"><button class="nav-btn btn-next" onclick="goStep(2)">Next</button></div>
</div>

<div class="step" id="step2">
  <div class="step-header">Step 2: Select your symptoms</div>
  <div class="symptoms-grid" id="symptomGrid"></div>
  <div class="nav-btns"><button class="nav-btn btn-back" onclick="goStep(1)">Back</button><button class="nav-btn btn-next" onclick="goStep(3)">Next</button></div>
</div>

<div class="step" id="step3">
  <div class="step-header">Step 3: How long have you had these symptoms?</div>
  <div class="duration-options" id="durOptions"></div>
  <div class="nav-btns"><button class="nav-btn btn-back" onclick="goStep(2)">Back</button><button class="nav-btn btn-next" onclick="analyze()">Get Assessment</button></div>
</div>

<div class="step" id="step4">
  <div class="step-header">Assessment Result</div>
  <div id="resultArea"></div>
  <div class="nav-btns"><button class="nav-btn btn-restart" onclick="restart()">Start Over</button></div>
</div>
</div>
<script>
const REGIONS=['Head','Chest','Abdomen','Back','Arms','Legs','Throat','Skin','General'];
const SYMPTOMS={
  Head:['Headache','Dizziness','Blurred vision','Confusion','Migraine','Fever','Nausea'],
  Chest:['Chest pain','Shortness of breath','Rapid heartbeat','Cough','Wheezing','Chest tightness'],
  Abdomen:['Stomach pain','Nausea','Vomiting','Diarrhea','Bloating','Loss of appetite','Blood in stool'],
  Back:['Lower back pain','Upper back pain','Stiffness','Numbness','Sciatica','Muscle spasm'],
  Arms:['Joint pain','Swelling','Numbness','Weakness','Tingling','Limited range of motion'],
  Legs:['Leg pain','Swelling','Numbness','Cramps','Varicose veins','Difficulty walking'],
  Throat:['Sore throat','Difficulty swallowing','Hoarseness','Swollen glands','Dry cough'],
  Skin:['Rash','Itching','Hives','Discoloration','Lumps','Bruising','Wound'],
  General:['Fatigue','Weight loss','Night sweats','Fever','Chills','Body aches','Insomnia']
};
const DURATIONS=['Less than 24 hours','1-3 days','4-7 days','1-2 weeks','More than 2 weeks','Months'];

let selectedRegion='',selectedSymptoms=[],selectedDuration='';

// Render regions
document.getElementById('bodyRegions').innerHTML=REGIONS.map(r=>`<div class="body-region" onclick="selectRegion(this,'${r}')">${r}</div>`).join('');

function selectRegion(el,region){document.querySelectorAll('.body-region').forEach(e=>e.classList.remove('selected'));el.classList.add('selected');selectedRegion=region;
  document.getElementById('symptomGrid').innerHTML=SYMPTOMS[region].map(s=>`<div class="symptom-chip" onclick="toggleSymptom(this,'${s}')">${s}</div>`).join('')}
function toggleSymptom(el,s){el.classList.toggle('selected');if(selectedSymptoms.includes(s))selectedSymptoms=selectedSymptoms.filter(x=>x!==s);else selectedSymptoms.push(s)}

// Duration
document.getElementById('durOptions').innerHTML=DURATIONS.map(d=>`<button class="dur-btn" onclick="selectDuration(this,'${d}')">${d}</button>`).join('');
function selectDuration(el,d){document.querySelectorAll('.dur-btn').forEach(e=>e.classList.remove('selected'));el.classList.add('selected');selectedDuration=d}

function goStep(n){document.querySelectorAll('.step').forEach(s=>s.classList.remove('active'));document.getElementById('step'+n).classList.add('active')}
function restart(){selectedRegion='';selectedSymptoms=[];selectedDuration='';document.querySelectorAll('.selected').forEach(e=>e.classList.remove('selected'));goStep(1)}

function analyze(){
  if(!selectedSymptoms.length){alert('Please select at least one symptom');return}
  // Triage logic (simplified rule-based)
  let level='self-care',advice=[],conditions=[];
  const emergency=['Chest pain','Shortness of breath','Confusion','Blood in stool','Difficulty breathing'];
  const urgent=['Rapid heartbeat','Blurred vision','Numbness','High fever','Difficulty swallowing'];

  if(selectedSymptoms.some(s=>emergency.includes(s))){level='emergency';conditions.push('Possible cardiovascular or neurological emergency');
    advice=['Call emergency services (911) immediately','Do not drive yourself to the hospital','Stay calm and sit or lie down','If chest pain: chew an aspirin if not allergic']}
  else if(selectedSymptoms.some(s=>urgent.includes(s))||selectedDuration.includes('week')){level='urgent';conditions.push('Condition may require prompt medical attention');
    advice=['Schedule a same-day or next-day doctor appointment','Go to urgent care if symptoms worsen','Keep a symptom diary','Do not ignore worsening symptoms']}
  else if(selectedDuration.includes('day')&&selectedSymptoms.length>=3){level='routine';conditions.push('Multiple symptoms suggest a developing condition');
    advice=['Schedule a routine appointment within a few days','Rest and stay hydrated','Monitor for any new or worsening symptoms','Take OTC medications as appropriate for symptom relief']}
  else{conditions.push('Symptoms appear manageable with self-care');
    advice=['Rest and adequate hydration','Over-the-counter remedies as appropriate','Monitor symptoms for 24-48 hours','Seek care if symptoms worsen or persist beyond 7 days']}

  const levelLabels={emergency:'Emergency — Seek immediate care',urgent:'Urgent — See a doctor soon',routine:'Routine — Schedule an appointment','self-care':'Self-Care — Monitor at home'};
  const levelClass={emergency:'level-emergency',urgent:'level-urgent',routine:'level-routine','self-care':'level-self-care'};

  document.getElementById('resultArea').innerHTML=`
    <div class="result">
      <span class="triage-level ${levelClass[level]}">${levelLabels[level]}</span>
      <p style="margin:12px 0;font-size:14px"><strong>Region:</strong> ${selectedRegion} | <strong>Symptoms:</strong> ${selectedSymptoms.join(', ')}</p>
      <p style="font-size:13px;color:#94a3b8"><strong>Duration:</strong> ${selectedDuration}</p>
      <p style="margin-top:12px;font-size:14px"><strong>Possible concern:</strong> ${conditions.join('; ')}</p>
      <ul class="advice-list">${advice.map(a=>'<li>'+a+'</li>').join('')}</ul>
      <div class="warning">&#9888; This is an AI-generated assessment for informational purposes only. It does not constitute medical advice. Always consult a healthcare professional for proper diagnosis and treatment.</div>
    </div>`;
  goStep(4);
}
</script></body></html>
