</style></head><body>
<div class="app">
<h1>Om Legal</h1>
<p class="subtitle">AI-Powered Legal Document Analyzer</p>
<div class="disclaimer">&#9888; This tool provides general legal information only. It is NOT a substitute for professional legal advice. Always consult a qualified attorney for legal matters.</div>

<div class="upload-area" onclick="document.getElementById('docInput').focus()">
  <div class="icon">&#128221;</div>
  <p>Paste your contract or legal document below</p>
</div>
<textarea id="docInput" placeholder="Paste your contract, NDA, lease agreement, terms of service, or any legal document here..."></textarea>
<button class="analyze-btn" id="analyzeBtn" onclick="analyzeDocument()">Analyze Document</button>

<div class="results" id="results">
  <div class="section">
    <h3>&#128200; Risk Assessment</h3>
    <div class="risk-score" id="riskScore"></div>
  </div>
  <div class="section">
    <h3>&#128209; Plain Language Summary</h3>
    <div class="summary-text" id="summary"></div>
  </div>
  <div class="section">
    <h3>&#128270; Key Clauses Identified</h3>
    <div id="clauses"></div>
  </div>
  <div class="section">
    <h3>&#9888; Risk Flags</h3>
    <ul class="flag-list" id="flags"></ul>
  </div>
  <div class="section">
    <h3>&#9989; Recommended Actions</h3>
    <ul class="action-list" id="actions"></ul>
  </div>
</div>
</div>
<script>
const CLAUSE_PATTERNS=[
  {pattern:/indemnif/i,type:'risk',label:'Indemnification',desc:'You may be held liable for damages or losses'},
  {pattern:/non-?compete|restrictive covenant/i,type:'risk',label:'Non-Compete',desc:'Restricts your ability to work with competitors'},
  {pattern:/terminat/i,type:'neutral',label:'Termination',desc:'Conditions under which the agreement can end'},
  {pattern:/confidential|non-?disclosure|NDA/i,type:'neutral',label:'Confidentiality',desc:'Restrictions on sharing information'},
  {pattern:/intellectual property|IP|patent|copyright/i,type:'risk',label:'IP Assignment',desc:'Transfer of intellectual property rights'},
  {pattern:/arbitration|mediation|dispute/i,type:'risk',label:'Dispute Resolution',desc:'How conflicts will be resolved (may limit court access)'},
  {pattern:/limitation of liability|cap.*liability/i,type:'risk',label:'Liability Cap',desc:'Limits maximum damages you can recover'},
  {pattern:/warranty|guarantee/i,type:'neutral',label:'Warranties',desc:'Promises about quality or performance'},
  {pattern:/force majeure|act of god/i,type:'favorable',label:'Force Majeure',desc:'Protection from unforeseeable circumstances'},
  {pattern:/payment|compensation|fee|salary/i,type:'neutral',label:'Payment Terms',desc:'Financial obligations and schedule'},
  {pattern:/governing law|jurisdiction/i,type:'neutral',label:'Jurisdiction',desc:'Which laws and courts apply'},
  {pattern:/automatic.*renew|auto-?renew/i,type:'risk',label:'Auto-Renewal',desc:'Contract renews automatically without action'},
  {pattern:/unlimited|perpetual|irrevocable/i,type:'risk',label:'Unlimited Terms',desc:'Terms with no time boundary or reversal'},
  {pattern:/mutual|both parties/i,type:'favorable',label:'Mutual Obligations',desc:'Balanced obligations for both parties'},
  {pattern:/30.?day|notice period|written notice/i,type:'favorable',label:'Notice Period',desc:'Time given before changes or termination'},
];

function analyzeDocument(){
  const text=document.getElementById('docInput').value.trim();
  if(!text||text.length<50){alert('Please paste a document (at least 50 characters)');return}

  // Extract sentences
  const sentences=text.split(/[.;\n]+/).filter(s=>s.trim().length>20);

  // Find clauses
  let foundClauses=[];
  let riskCount=0,totalClauses=0;
  for(const sentence of sentences){
    for(const cp of CLAUSE_PATTERNS){
      if(cp.pattern.test(sentence)){
        foundClauses.push({...cp,text:sentence.trim().slice(0,200)});
        totalClauses++;if(cp.type==='risk')riskCount++;break}}}

  // Risk score
  const riskPct=totalClauses?Math.round((riskCount/totalClauses)*100):0;
  const riskLevel=riskPct>60?'high':riskPct>30?'med':'low';
  const riskLabels={low:'Low Risk',med:'Medium Risk',high:'High Risk'};
  const riskColors={low:'#4ade80',med:'#fbbf24',high:'#ef4444'};

  document.getElementById('riskScore').innerHTML=`<span class="risk-label" style="color:${riskColors[riskLevel]}">${riskLabels[riskLevel]} (${riskPct}%)</span><div class="risk-bar"><div class="risk-fill" style="width:${riskPct}%;background:${riskColors[riskLevel]}"></div></div>`;

  // Summary
  const docType=text.match(/NDA|non-?disclosure/i)?'Non-Disclosure Agreement':text.match(/lease|tenant|landlord/i)?'Lease Agreement':text.match(/employ/i)?'Employment Contract':text.match(/terms of service|ToS/i)?'Terms of Service':'Legal Document';
  document.getElementById('summary').innerHTML=`This appears to be a <strong>${docType}</strong> with ${sentences.length} clauses. ${totalClauses} key legal provisions were identified, of which ${riskCount} contain potential risk factors. ${riskLevel==='high'?'This document has significant risk clauses that warrant careful review by a legal professional.':riskLevel==='med'?'Some clauses may need negotiation or clarification.':'The document appears relatively balanced.'}`;

  // Clauses
  document.getElementById('clauses').innerHTML=foundClauses.slice(0,10).map(c=>`<div class="clause ${c.type}"><div class="clause-type ${c.type}">${c.label} — ${c.desc}</div><div>${c.text}...</div></div>`).join('')||'<p style="color:#64748b">No specific clauses identified</p>';

  // Flags
  const flags=foundClauses.filter(c=>c.type==='risk');
  document.getElementById('flags').innerHTML=flags.length?flags.map(f=>`<li><strong>${f.label}:</strong> ${f.desc}</li>`).join(''):'<li>No significant risk flags detected</li>';

  // Actions
  const actions=['Review all highlighted risk clauses with an attorney','Negotiate indemnification caps if present','Ensure termination clauses are fair and mutual','Verify jurisdiction is acceptable to you','Check for hidden auto-renewal terms','Request written amendments for unfavorable clauses'];
  document.getElementById('actions').innerHTML=actions.slice(0,riskCount>3?6:4).map(a=>`<li>${a}</li>`).join('');

  document.getElementById('results').classList.add('show');
}
</script></body></html>
